//! cachet-core holds every protocol decision as a total function over
//! injected values: narinfo grammar, key validation, lease and generation
//! documents, multipart part planning, GC mark and sweep, OIDC claim
//! policy, and the error-code table (CLAUDE.md §1, §4). It performs no I/O
//! and reads no ambient clock or entropy; the Clock and Rng traits are
//! defined here and implemented at the edges.

#![forbid(unsafe_code)]

//! cachet-crypto is the only place hashing, signing, and decompression
//! happen (CLAUDE.md §5): SHA-256 over streams, nix base32 and base64 hash
//! encodings, ed25519 signing of the nix narinfo fingerprint, zstd
//! decoding via ruzstd, and RS256 signature verification. Every function is
//! pure and every dependency builds for wasm32-unknown-unknown; deny.toml
//! bans ring, aws-lc, and the C zstd crate from the whole tree.

#![forbid(unsafe_code)]

//! cachet-api is the HTTP surface, expressed with `http`-crate typed
//! handlers and utoipa derive macros (CLAUDE.md §1, docs/openapi.yaml). The
//! code is the source of truth for the OpenAPI document: `just openapi`
//! regenerates docs/openapi.yaml from these handlers and CI fails on drift.
//! Handlers are platform-free; the worker crate adapts them to workers-rs
//! request and response types.

#![forbid(unsafe_code)]

//! cachet-worker is the deployable leaf (CLAUDE.md §4). It adapts the
//! Cloudflare request, environment, R2 bucket, KV namespace, Cache API, and
//! outbound GitHub calls into cachet-core decisions and renders results.
//! All ambient clock, entropy, and I/O live here behind the seams; the
//! signing key enters only as a Workers secret binding and is never logged
//! or returned.

#![forbid(unsafe_code)]

use worker::{event, Context, Env, Request, Response, Result};

/// The fetch entry point. P0 spine only: routing lands in P4 with the read
/// path, and P5 adds writes (CLAUDE.md §1).
#[event(fetch)]
async fn fetch(_req: Request, _env: Env, _ctx: Context) -> Result<Response> {
    Response::ok("cachet")
}

//! cachet-push is the writer-side pipeline as a native library (CLAUDE.md
//! §1): snapshot the local store, diff against a previous snapshot, filter
//! against the cache and the upstream substituter, stage through nix with
//! zstd compression, upload NARs before narinfos with a fresh OIDC token
//! per request, and renew the project lease on the default branch. The CI
//! contract is to log and exit zero on failure rather than fail the job
//! (docs/design/action.md).

#![forbid(unsafe_code)]

//! The `cachet` binary. Subcommands land in P8: login, setup, push,
//! keygen, doctor (docs/design/cli.md).

use clap::Parser;

/// cachet: client for a self-hosted nix binary cache.
#[derive(Parser)]
#[command(version, about)]
struct Cli {}

fn main() {
    let _cli = Cli::parse();
}

{
  description = "cachet: a self-hostable nix binary cache on Cloudflare Workers";

  # why: plain github: refs keep the flake registry out of the dependency
  # path. The channel is nixos-unstable because only dev and build tools come
  # from it; the compiler comes from rust-toolchain.toml through rust-overlay.
  # flake.lock pins every revision, and dependabot proposes updates.
  # why: no nixConfig block. extra-substituters is a restricted client
  # setting that a non-trusted user ignores, so cache trust is wired in CI,
  # not committed here.
  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";

    flake-parts.url = "github:hercules-ci/flake-parts";
    flake-parts.inputs.nixpkgs-lib.follows = "nixpkgs";

    treefmt-nix.url = "github:numtide/treefmt-nix";
    treefmt-nix.inputs.nixpkgs.follows = "nixpkgs";

    # why: crane builds the workspace as a proper derivation, compiling the
    # dependency closure once and substituting it into every check.
    crane.url = "github:ipetkov/crane";

    # why: rust-overlay resolves the exact toolchain pinned in
    # rust-toolchain.toml, the single source of truth for the compiler.
    rust-overlay.url = "github:oxalica/rust-overlay";
    rust-overlay.inputs.nixpkgs.follows = "nixpkgs";
  };

  outputs =
    inputs@{ flake-parts, ... }:
    flake-parts.lib.mkFlake { inherit inputs; } {
      # The two CI and dev-machine architectures in both operating systems.
      # The production target (wasm32-unknown-unknown) is a Rust target, not
      # a nix system.
      systems = [
        "x86_64-linux"
        "aarch64-linux"
        "x86_64-darwin"
        "aarch64-darwin"
      ];

      imports = [
        inputs.treefmt-nix.flakeModule
        ./nix/rust-workspace.nix
        ./nix/treefmt.nix
        ./nix/devshell.nix
        ./nix/checks.nix
      ];
    };
}

# One toolchain resolution, one dependency closure: every check shares
# compiled dependencies through _module.args, and no module re-derives them.
# cachet-worker builds for wasm32 only, so the host closures exclude it; the
# wasm build is a dedicated verb (justfile) rather than a host check.
{ inputs, lib, ... }:
{
  perSystem =
    { system, ... }:
    let
      pkgs = import inputs.nixpkgs {
        inherit system;
        overlays = [ (import inputs.rust-overlay) ];
      };
      toolchain = pkgs.rust-bin.fromRustupToolchainFile ../rust-toolchain.toml;
      craneLib = (inputs.crane.mkLib pkgs).overrideToolchain toolchain;
      src = lib.cleanSourceWith {
        src = ../.;
        filter =
          path: type:
          let
            rel = lib.removePrefix (toString ../. + "/") (toString path);
          in
          (craneLib.filterCargoSources path type)
          # why: clippy reads the disallowed lists at lint time.
          || (rel == "clippy.toml")
          # why: nextest reads the ci profile at run time.
          || (rel == ".config/nextest.toml")
          # why: the committed OpenAPI document is served byte-for-byte and
          # compared by the golden lane.
          || (rel == "docs/openapi.yaml")
          # why: golden vectors against real nix outputs live outside cargo's
          # file list.
          || (lib.hasInfix "/fixtures/" rel)
          # why: insta snapshots are the golden lane's expected bytes;
          # cargo's source filter does not know them.
          || (lib.hasSuffix ".snap" rel);
      };
      commonArgs = {
        inherit src;
        pname = "cachet";
        version = "0.0.1";
        strictDeps = true;
      };
      # why: deny.toml stays out of the crane source on purpose: the deny
      # gate fetches the advisory database and is impure by design, so it
      # runs in the dev shell, never as a flake check.
      cargoArtifacts = craneLib.buildDepsOnly (
        commonArgs
        // {
          # why: cachet-worker is wasm32-only; the host closure covers the
          # five crates that build natively.
          cargoExtraArgs = "--workspace --exclude cachet-worker --all-features --locked";
        }
      );
    in
    {
      _module.args = {
        inherit
          pkgs
          toolchain
          craneLib
          src
          commonArgs
          cargoArtifacts
          ;
      };
    };
}

# The formatter gateway: one command formats every language it covers.
# Markdown is excluded globally: prose is hand-wrapped, and the CLAUDE.md
# import manifest parses by line.
{ ... }:
{
  perSystem =
    { config, toolchain, ... }:
    {
      # why: the auto check would be named treefmt; every gate carries
      # exactly one name across the flake output, the just verb, and the CI
      # job, so this module defines checks.fmt itself.
      treefmt = {
        flakeCheck = false;
        projectRootFile = "flake.nix";
        programs.nixfmt.enable = true;
        # why: the pinned toolchain's own rustfmt, so nix fmt never fights
        # cargo fmt.
        programs.rustfmt = {
          enable = true;
          package = toolchain;
        };
        # yaml and json; prettier has no TOML parser, TOML is hand-formatted.
        programs.prettier.enable = true;
        programs.shfmt.enable = true;
        settings.global.excludes = [
          "*.md"
          "*.lock"
          ".envrc"
          "result"
          "result-*"
          ".direnv/**"
          "target/**"
          "**/node_modules/**"
          "crates/cachet-worker/build/**"
          "dist/**"
          ".alchemy/**"
          "wrangler.local.jsonc"
        ];
      };
      checks.fmt = config.treefmt.build.check ../.;
    };
}

# The gate set: one checks.<system> attribute per sandbox-pure gate, one CI
# job per gate. CLAUDE.md §0 binds this list: a gate is named anywhere in
# the repo only when it exists here or as a just verb. The impure gates
# (deny fetches the advisory database; kani downloads its own toolchain) are
# just verbs, not derivations, because a sandboxed build cannot reach the
# network.
{ ... }:
{
  perSystem =
    {
      pkgs,
      craneLib,
      cargoArtifacts,
      commonArgs,
      ...
    }:
    {
      checks = {
        # why: crane appends its own --release --locked; pass neither again.
        # cachet-worker is wasm32-only and excluded from the host closure.
        clippy = craneLib.cargoClippy (
          commonArgs
          // {
            inherit cargoArtifacts;
            cargoClippyExtraArgs = "--workspace --exclude cachet-worker --all-targets --all-features -- --deny warnings";
          }
        );

        unit = craneLib.cargoNextest (
          commonArgs
          // {
            inherit cargoArtifacts;
            # why: nextest fails an empty suite, and a red lane beats a
            # seeded silence.
            cargoNextestExtraArgs = "--workspace --exclude cachet-worker --profile ci";
          }
        );

        # why: the unit gate would pass these cases hidden in the full
        # suite; the lane runs them isolated so a property failure is its
        # own signal.
        property = craneLib.cargoTest (
          commonArgs
          // {
            inherit cargoArtifacts;
            cargoTestExtraArgs = "--workspace --exclude cachet-worker --test property";
          }
        );

        # why: snapshots commit with their code; drift is a failed test,
        # never a silent refresh in CI.
        golden = craneLib.cargoTest (
          commonArgs
          // {
            inherit cargoArtifacts;
            INSTA_UPDATE = "no";
            cargoTestExtraArgs = "--workspace --exclude cachet-worker --test golden";
          }
        );

        # why: the non-language gates run committed scripts over committed
        # inputs inside the sandbox; the gate is the script's exit code, and
        # no git state can leak in.
        doc-manifest =
          pkgs.runCommand "doc-manifest"
            {
              nativeBuildInputs = [
                pkgs.bash
                pkgs.gawk
                pkgs.findutils
                pkgs.coreutils
                pkgs.gnugrep
                pkgs.gnused
              ];
            }
            ''
              cp ${../CLAUDE.md} CLAUDE.md
              cp ${../README.md} README.md
              cp ${../PROSE.md} PROSE.md
              cp ${../SECURITY.md} SECURITY.md
              cp -r ${../docs} docs
              cp ${../scripts/check-doc-manifest.sh} check-doc-manifest.sh
              bash ./check-doc-manifest.sh .
              touch $out
            '';

        lane-manifest =
          pkgs.runCommand "lane-manifest"
            {
              nativeBuildInputs = [
                pkgs.bash
                pkgs.gawk
                pkgs.findutils
                pkgs.coreutils
                pkgs.gnugrep
                pkgs.gnused
              ];
            }
            ''
              cp -r ${../docs} docs
              mkdir -p .github/workflows
              cp ${../.github/workflows/ci.yml} .github/workflows/ci.yml
              cp ${../scripts/check-lane-manifest.sh} check-lane-manifest.sh
              bash ./check-lane-manifest.sh .
              touch $out
            '';

        actionlint =
          pkgs.runCommand "actionlint"
            {
              nativeBuildInputs = [ pkgs.actionlint ];
            }
            ''
              actionlint ${../.github/workflows}/ci.yml
              touch $out
            '';

        scripts =
          pkgs.runCommand "scripts"
            {
              nativeBuildInputs = [ pkgs.shellcheck ];
            }
            ''
              shellcheck ${../scripts}/*.sh
              touch $out
            '';
      };
    };
}

