1	//! The core domain's pure laws over arbitrary inputs
2	//! (docs/testing/property.md). Email canonicalization is total and
3	//! idempotent, the UUIDv7 layout orders by its millisecond prefix, and the
4	//! id format round-trips through its parser, each over a swept space rather
5	//! than one fixed example.
6	
7	use core::str::FromStr;
8	
9	use hegel::TestCase;
10	use hegel::generators as gs;
11	
12	use sesame_core::ids::UserId;
13	use sesame_core::model::{EMAIL_MAX_LEN, EmailAddress, TimestampMillis};
14	use sesame_core::seams::rng::layout;
15	
16	const LOCAL_ALPHABET: &[u8] =
17	    b"REDACTED._%+-";
18	const DOMAIN_ALPHABET: &[u8] = b"REDACTED.-";
19	
20	fn draw_with_alphabet(tc: &TestCase, alphabet: &[u8]) -> String {
21	    let bytes = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(60));
22	    let mut out = String::from('a');
23	    out.extend(
24	        bytes
25	            .iter()
26	            .map(|b| alphabet[usize::from(*b) % alphabet.len()] as char),
27	    );
28	    out
29	}
30	
31	#[hegel::test(test_cases = 256)]
32	fn email_construction_is_total(tc: TestCase) {
33	    let bytes: Vec<u8> = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(300));
34	    let raw = String::from_utf8_lossy(&bytes);
35	    // Construction answers Ok or a typed rejection, never a panic, for any
36	    // byte string at all.
37	    if let Ok(email) = EmailAddress::new(&raw) {
38	        assert!(email.as_str().len() <= EMAIL_MAX_LEN);
39	        assert_eq!(email.as_str(), email.as_str().to_lowercase());
40	        let again = EmailAddress::new(email.as_str()).expect("the canonical form parses");
41	        assert_eq!(email, again, "canonicalization is idempotent");
42	    }
43	}
44	
45	#[hegel::test(test_cases = 256)]
46	fn canonicalization_is_fold_equivalent(tc: TestCase) {
47	    let local = draw_with_alphabet(&tc, LOCAL_ALPHABET);
48	    let domain = draw_with_alphabet(&tc, DOMAIN_ALPHABET);
49	    let raw = format!("{local}@{domain}");
50	    let folded: String = raw
51	        .chars()
52	        .map(|c| {
53	            if tc.draw(gs::booleans()) {
54	                c.to_ascii_uppercase()
55	            } else {
56	                c
57	            }
58	        })
59	        .collect();
60	    let original = EmailAddress::new(&raw).expect("the constrained alphabet is valid");
61	    let variant = EmailAddress::new(&folded).expect("case folding keeps the input valid");
62	    assert_eq!(original, variant, "case never changes the canonical form");
63	    let twice = EmailAddress::new(original.as_str()).expect("the canonical form parses");
64	    assert_eq!(original, twice);
65	}
