//! Named wire constants shared by every crate (CLAUDE.md §4, §6). Bounds
//! stay here so the worker, the CLI, and the action cannot disagree about a
//! limit by drifting copies.

/// The exact body of `GET /nix-cache-info`. Priority 30 sorts cachet ahead
/// of cache.nixos.org (priority 40) in a client's substituter order, and
/// WantMassQuery permits nix to batch narinfo lookups.
pub const NIX_CACHE_INFO: &str = "StoreDir: /nix/store\nWantMassQuery: 1\nPriority: 30\n";

/// The nix base32 alphabet: lowercase, excluding e, o, u, and t. Store-path
/// hashes are 32 chars; NAR file hashes are 52 (docs/design/wire-formats.md).
pub const NIX_BASE32_ALPHABET: &str = "REDACTED";

/// A narinfo body larger than this is refused with body_too_large: narinfos
/// are a few hundred bytes in practice, so 64 KiB is generous headroom and
/// still a hard guard in front of the parser.
pub const NARINFO_BYTES_MAX: u64 = 65_536;

/// Single-shot NAR PUT refuses bodies larger than this with body_too_large:
/// 90 MiB of headroom under Cloudflare's 100 MB edge request cap
/// (docs/design/worker.md). Larger NARs use the multipart routes.
pub const UPLOAD_SINGLE_MAX_BYTES: u64 = 94_371_800;

/// Every multipart part except the last is exactly this size; the last is
/// the declared remainder (docs/design/worker.md).
pub const UPLOAD_PART_BYTES: u64 = 67_108_864;

/// The multipart protocol rejects a plan with more than this many parts.
pub const MULTIPART_PARTS_MAX: u64 = 1_000;

/// The push pipeline refuses closures adding more than this many store
/// paths, matching the previous implementation's guard.
pub const PUSH_PATHS_MAX: u64 = 4_096;

//! cachet-core holds every protocol decision as a total function over
//! injected values: narinfo grammar, key validation, lease and generation
//! documents, multipart part planning, GC mark and sweep, OIDC claim
//! policy, and the error-code table (CLAUDE.md §1, §4). It performs no I/O
//! and reads no ambient clock or entropy; the Clock and Rng traits are
//! defined here and implemented at the edges.

#![forbid(unsafe_code)]
#![warn(missing_docs)]

pub mod constants;

//! The property lane's convention stub (docs/testing/property.md): one
//! `tests/property.rs` per crate with laws, and the real wire laws land
//! with P1's grammar and GC modules. This case exists so the lane runs
//! nonzero work from the first commit and the harness wiring (draw, count,
//! shrink) is proven before the laws arrive.

use hegel::TestCase;
use hegel::generators as gs;

#[hegel::test(test_cases = 64)]
fn byte_layout_round_trips(tc: TestCase) {
    let value = tc.draw(gs::integers::<u64>());
    assert_eq!(
        value,
        u64::from_le_bytes(value.to_le_bytes()),
        "the u64 LE layout round-trips"
    );
}

//! The golden lane's first locked wires (docs/testing/golden.md):
//! `/nix-cache-info` is the contract every nix client reads first, and the
//! bound constants land in docs/contracts.md as this table grows. Snapshots
//! run with INSTA_UPDATE=no in the gate, so an intentional change updates
//! the snap file in the same commit.

use cachet_core::constants::{
    MULTIPART_PARTS_MAX, NARINFO_BYTES_MAX, NIX_BASE32_ALPHABET, NIX_CACHE_INFO, PUSH_PATHS_MAX,
    UPLOAD_PART_BYTES, UPLOAD_SINGLE_MAX_BYTES,
};

#[test]
fn nix_cache_info_body_is_exact() {
    insta::assert_snapshot!(NIX_CACHE_INFO, @"StoreDir: /nix/store\nWantMassQuery: 1\nPriority: 30\n");
}

#[test]
fn bound_constants_are_the_contract() {
    let snap = format!("{NARINFO_BYTES_MAX} {UPLOAD_SINGLE_MAX_BYTES} {UPLOAD_PART_BYTES} {MULTIPART_PARTS_MAX} {PUSH_PATHS_MAX}");
    insta::assert_snapshot!(snap, @"65536 94371800 67108864 1000 4096");
}

#[test]
fn nix_base32_alphabet_matches_nix() {
    assert_eq!(NIX_BASE32_ALPHABET, "REDACTED");
    assert_eq!(NIX_BASE32_ALPHABET.len(), 32);
    for dropped in [b'e', b'o', b'u', b't'] {
        assert!(
            !NIX_BASE32_ALPHABET.contains(char::from(dropped)),
            "the nix alphabet drops vowels e, o, u, and t"
        );
    }
}

//! Multipart part planning (CLAUDE.md §4). The upload protocol declares
//! the total byte count up front, and every part except the last carries
//! exactly [`UPLOAD_PART_BYTES`]; the server verifies completeness against
//! this plan, so client and worker compute it from one function
//! (docs/design/worker.md, docs/testing/kani.md).

use crate::constants::{MULTIPART_PARTS_MAX, UPLOAD_PART_BYTES};
use crate::error::ClientError;

/// One planned part: a one-based part number and its exact byte length.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Part {
    /// One-based part number, as the wire protocol carries it.
    pub number: u64,
    /// The exact byte length of this part.
    pub len: u64,
}

/// The full plan for one upload.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PartPlan {
    /// The declared total byte count of the upload.
    pub total_bytes: u64,
    /// The parts, in ascending order.
    pub parts: Vec<Part>,
}

/// Plan the multipart upload for an object of `total_bytes`.
///
/// # Errors
///
/// - [`ClientError::LengthRequired`] when the total is zero: the protocol
///   requires a declared positive total before any part is accepted.
/// - [`ClientError::BodyTooLarge`] when the total exceeds
///   [`UPLOAD_PART_BYTES`] times [`MULTIPART_PARTS_MAX`].
pub fn part_plan(total_bytes: u64) -> Result<PartPlan, ClientError> {
    if total_bytes == 0 {
        return Err(ClientError::LengthRequired);
    }
    if total_bytes > UPLOAD_PART_BYTES * MULTIPART_PARTS_MAX {
        return Err(ClientError::BodyTooLarge);
    }
    let full = total_bytes / UPLOAD_PART_BYTES;
    let remainder = total_bytes % UPLOAD_PART_BYTES;
    let count = if remainder == 0 { full } else { full + 1 };
    let mut parts = Vec::with_capacity(usize::try_from(count).expect("count ≤ 1000"));
    for n in 1..=count {
        let len = if n == count && remainder != 0 {
            remainder
        } else {
            UPLOAD_PART_BYTES
        };
        parts.push(Part { number: n, len });
    }
    debug_assert_eq!(parts.iter().map(|p| p.len).sum::<u64>(), total_bytes);
    Ok(PartPlan { total_bytes, parts })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn zero_total_is_refused() {
        assert_eq!(part_plan(0), Err(ClientError::LengthRequired));
    }

    #[test]
    fn over_the_cap_is_refused() {
        assert_eq!(
            part_plan(UPLOAD_PART_BYTES * MULTIPART_PARTS_MAX + 1),
            Err(ClientError::BodyTooLarge)
        );
    }

    #[test]
    fn exact_multiple_has_no_short_tail() {
        let plan = part_plan(2 * UPLOAD_PART_BYTES).expect("two full parts");
        assert_eq!(plan.parts.len(), 2);
        assert!(plan.parts.iter().all(|p| p.len == UPLOAD_PART_BYTES));
    }

    #[test]
    fn single_part_is_short() {
        let plan = part_plan(7).expect("one short part");
        assert_eq!(plan.parts.len(), 1);
        assert_eq!(plan.parts[0].len, 7);
    }
}

#[cfg(kani)]
mod proofs {
    use super::*;

    /// For every admissible total, the plan sums exactly, every part before
    /// the last is full, the last is positive, and the count stays inside
    /// the cap; for every inadmissible total, planning is a typed refusal.
    #[kani::proof]
    #[kani::unwind(17)]
    fn part_plan_sums_and_bounds() {
        let total: u64 = kani::any();
        match part_plan(total) {
            Ok(plan) => {
                assert!(
                    total > 0 && total <= UPLOAD_PART_BYTES * MULTIPART_PARTS_MAX,
                    "success implies an admissible total"
                );
                assert_eq!(
                    plan.parts.iter().map(|p| p.len).sum::<u64>(),
                    total,
                    "parts sum to the declared total"
                );
                assert!(
                    u64::try_from(plan.parts.len()).expect("len fits") <= MULTIPART_PARTS_MAX,
                    "count stays in the cap"
                );
                assert_eq!(plan.parts[0].number, 1);
                let last = plan.parts.len() - 1;
                for (i, part) in plan.parts.iter().enumerate() {
                    assert_eq!(part.number, u64::try_from(i).expect("fits") + 1);
                    assert!(part.len > 0, "no empty part");
                    if i != last {
                        assert_eq!(part.len, UPLOAD_PART_BYTES, "non-final parts are full");
                    }
                }
            }
            Err(code) => {
                assert!(
                    total == 0 || total > UPLOAD_PART_BYTES * MULTIPART_PARTS_MAX,
                    "refusal implies an inadmissible total"
                );
                assert!(matches!(
                    code,
                    ClientError::LengthRequired | ClientError::BodyTooLarge
                ));
            }
        }
    }
}

//! The error taxonomy (CLAUDE.md §7). Every client-reachable failure is one
//! of these codes with a fixed HTTP status; the worker renders it as an RFC
//! 9457 problem+json body. The table only grows: previous codes and their
//! statuses never change, so deployed clients keep matching.

use core::fmt;

/// A client-reachable failure with its wire vocabulary.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ClientError {
    /// A declared positive Content-Length or total byte count was absent.
    LengthRequired,
    /// The request, body, or planned upload exceeds a declared bound.
    BodyTooLarge,
}

impl ClientError {
    /// The HTTP status the worker answers with.
    pub const fn status(self) -> u16 {
        match self {
            Self::LengthRequired => 411,
            Self::BodyTooLarge => 413,
        }
    }

    /// The `code` field of the problem+json body.
    pub const fn code(self) -> &'static str {
        match self {
            Self::LengthRequired => "length_required",
            Self::BodyTooLarge => "body_too_large",
        }
    }
}

impl fmt::Display for ClientError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.code())
    }
}

impl std::error::Error for ClientError {}

