135	/** Validate the `References` field into checked basenames. */
136	function parseReferences(raw: string | undefined): Result<readonly string[]> {
137	    if (raw === undefined || raw.length === 0) {
138	        return ok([]);
139	    }
140	    const entries = raw.split(' ').filter((entry) => entry.length > 0);
141	    if (entries.length > NARINFO_REFERENCES_MAX) {
142	        // Invariant BOUNDED-WORK: this also caps the closure walk's fan-out from one node.
143	        return fail(
144	            'malformed_narinfo',
145	            `References exceeds ${String(NARINFO_REFERENCES_MAX)} entries`,
