157	/**
158	 * Parse a narinfo document.
159	 *
160	 * @example
161	 * ```ts
162	 * const parsed = parseNarinfo(await request.text());
163	 * if (!parsed.ok) return parsed;
164	 * const narKey = parsed.value.url;   // the object NEVER-DANGLE requires to exist
165	 * ```
166	 */
167	export function parseNarinfo(text: string): Result<Narinfo> {
168	    // Bound before splitting, so a huge document costs a length comparison.
169	    if (text.length > NARINFO_BYTES_MAX) {
170	        return fail('body_too_large', `a narinfo exceeds ${String(NARINFO_BYTES_MAX)} bytes`);
171	    }
172	
173	    const collected = collectFields(text);
174	    if (!collected.ok) {
175	        return collected;
176	    }
177	    const { single, signatures, extraLines } = collected.value;
178	
179	    const storePathText = single.get('StorePath');
180	    const urlText = single.get('URL');
181	    const narHashText = single.get('NarHash');
182	    const narSizeText = single.get('NarSize');
183	    if (
184	        storePathText === undefined ||
185	        urlText === undefined ||
186	        narHashText === undefined ||
