//! The auth decision policy (CLAUDE.md §1, §7): what a GitHub OIDC token
//! must prove to write, and how long a validated GitHub user token stays
//! believed for reads. These functions are total and clock-injected; the
//! worker's edge adapts headers and JWKS bytes into the values they
//! decide over.
//!
//! The boundaries, stated once: writes are OIDC-only; laptops are
//! read-only; an OIDC token's `repository_owner` must be one of the
//! configured orgs; lease renewal additionally requires the configured
//! default branch and a project equal to the token's `repository` claim.

use crate::constants::{
    ACCEPTED_ORGS_MAX, JWKS_CACHE_TTL_MS, OIDC_CLOCK_TOLERANCE_MS, OAUTH_STATE_TTL_MS,
    SESSION_TTL_MS, VERDICT_ALLOW_TTL_MS, VERDICT_DENY_TTL_MS,
};
use crate::error::{ClientError, Result};
use crate::types::{ProjectName, UnixMillis};

/// The OIDC issuer URL every token must carry exactly.
pub const OIDC_ISSUER: &str = "https://token.actions.githubusercontent.com";

/// The deployment configuration the policy checks against. Vars in the
/// stack supply it; production code never hardcodes identity.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OidcConfig {
    /// The GitHub orgs whose OIDC tokens may write.
    pub orgs: Vec<String>,
    /// The exact audience a token must name, one string, never a match
    /// against a list inside the token.
    pub audience: String,
    /// The default-branch ref lease renewal is pinned to.
    pub default_branch_ref: String,
}

impl OidcConfig {
    /// Validate the configuration itself: an empty org list, an org entry
    /// with whitespace, an empty audience, or more orgs than the cap is a
    /// deployment mistake, and the request path refuses it with
    /// `auth_unavailable` by construction because no token can pass the
    /// empty list. Validating here is cheaper than correcting a security
    /// boundary in production.
    pub fn validate(&self) -> Result<()> {
        if self.orgs.is_empty() || self.orgs.len() > ACCEPTED_ORGS_MAX {
            return Err(ClientError::AuthUnavailable);
        }
        if self
            .orgs
            .iter()
            .any(|org| org.is_empty() || org.bytes().any(|b| b.is_ascii_whitespace()))
        {
            return Err(ClientError::AuthUnavailable);
        }
        if self.audience.is_empty() || self.default_branch_ref.is_empty() {
            return Err(ClientError::AuthUnavailable);
        }
        Ok(())
    }
}

/// The claims a verified OIDC token proves, extracted for the rest of the
/// system.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OidcIdentity {
    /// `owner/repo` of the workflow run.
    pub repository: String,
    /// The owner half of `repository`.
    pub repository_owner: String,
    /// The ref the run happened on.
    pub ref_: String,
    /// The workflow run id, when present.
    pub run_id: String,
    /// The commit sha, when present.
    pub sha: String,
}

/// Read one required string claim; a missing or mistyped claim refuses the
/// token, it never degrades.
fn string_claim(raw: &serde_json::Value, name: &str) -> Result<String> {
    raw.get(name)
        .and_then(serde_json::Value::as_str)
        .map(str::to_string)
        .ok_or(ClientError::Unauthorized)
}

/// Read one required integer time claim.
fn time_claim(raw: &serde_json::Value, name: &str) -> Result<u64> {
    raw.get(name)
        .and_then(serde_json::Value::as_u64)
        .ok_or(ClientError::Unauthorized)
}

/// Check a decoded OIDC claim set against the deployment configuration.
/// Algorithm selection and signature verification happen before this runs;
/// this function decides whether a cryptographically valid token carries
/// what the deployment requires.
///
/// # Errors
///
/// [`ClientError::Unauthorized`] for issuer, audience, time, or shape
/// failures; [`ClientError::ForbiddenOrg`] for an out-of-org owner.
pub fn verify_claims(
    raw: &serde_json::Value,
    config: &OidcConfig,
    now: UnixMillis,
) -> Result<OidcIdentity> {
    config.validate()?;

    if string_claim(raw, "iss")? != OIDC_ISSUER {
        return Err(ClientError::Unauthorized);
    }
    // why: an aud that is an array is a *different* protocol obligation
    // (evaluate every entry), so it refuses rather than running partial
    // logic over one entry. Exact single-string equality is the whole
    // audience rule.
    match raw.get("aud") {
        Some(serde_json::Value::String(value)) if value == &config.audience => {}
        _ => return Err(ClientError::Unauthorized),
    }

    let now_ms = now.as_u64();
    let exp = time_claim(raw, "exp")?;
    if exp.checked_mul(1_000).ok_or(ClientError::Unauthorized)?
        < now_ms.saturating_sub(OIDC_CLOCK_TOLERANCE_MS)
    {
        return Err(ClientError::Unauthorized);
    }
    let iat = time_claim(raw, "iat")?;
    if iat.checked_mul(1_000).ok_or(ClientError::Unauthorized)?
        > now_ms.saturating_add(OIDC_CLOCK_TOLERANCE_MS)
    {
        return Err(ClientError::Unauthorized);
    }
    if let Some(nbf) = raw.get("nbf").and_then(serde_json::Value::as_u64) {
        if nbf.checked_mul(1_000).ok_or(ClientError::Unauthorized)?
            > now_ms.saturating_add(OIDC_CLOCK_TOLERANCE_MS)
        {
            return Err(ClientError::Unauthorized);
        }
    }

    let repository = string_claim(raw, "repository")?;
    let repository_owner = string_claim(raw, "repository_owner")?;
    let ref_ = string_claim(raw, "ref")?;

    // Exact membership in the configured list. No prefix matches, no
    // case folding: GitHub emits owner names in canonical form.
    if !config.orgs.iter().any(|org| org == &repository_owner) {
        return Err(ClientError::ForbiddenOrg);
    }

    Ok(OidcIdentity {
        repository,
        repository_owner,
        ref_,
        run_id: raw
            .get("run_id")
            .and_then(serde_json::Value::as_str)
            .unwrap_or(crate::constants::UNKNOWN_CLAIM)
            .to_string(),
        sha: raw
            .get("sha")
            .and_then(serde_json::Value::as_str)
            .unwrap_or(crate::constants::UNKNOWN_CLAIM)
            .to_string(),
    })
}

/// The lease-renewal gate: renewal must come from the configured default
/// branch.
///
/// # Errors
///
/// [`ClientError::ForbiddenRef`] on any other ref.
pub fn require_default_branch(identity: &OidcIdentity, config: &OidcConfig) -> Result<()> {
    if identity.ref_ == config.default_branch_ref {
        Ok(())
    } else {
        Err(ClientError::ForbiddenRef)
    }
}

/// The tenancy gate: a token may renew only its own repository's lease.
///
/// # Errors
///
/// [`ClientError::ForbiddenProject`] when the project's name does not equal
/// the hyphenated repository claim.
pub fn require_project_binding(identity: &OidcIdentity, project: &ProjectName) -> Result<()> {
    let derived = ProjectName::from_repository(&identity.repository)?;
    if &derived == project {
        Ok(())
    } else {
        Err(ClientError::ForbiddenProject)
    }
}

/// The kind of decision the JWKS cache policy produces.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum JwksDecision {
    /// Serve the cached document; it is inside its TTL.
    UseCached,
    /// Fetch fresh; the cache is empty or expired.
    Fetch,
}

/// The per-isolate JWKS cache policy: fresh inside the TTL, fetch
/// otherwise. Stale-fallback on a failed fetch is the edge's choice, not
/// this policy's: a stale document is better than an outage, and the TTL
/// still bounds acceptance of rotated-away keys.
pub fn decide_jwks(fetched_at_ms: Option<u64>, now: UnixMillis) -> JwksDecision {
    match fetched_at_ms {
        Some(at) if now.saturating_ms_since(UnixMillis::new(at)) < JWKS_CACHE_TTL_MS => {
            JwksDecision::UseCached
        }
        _ => JwksDecision::Fetch,
    }
}

/// The unknown-kid rule: one refetch per request, never a loop.
pub fn refetch_once_allowed(already_refetched: bool) -> bool {
    !already_refetched
}

/// The verdict outcome for one GitHub user token.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct Verdict {
    /// The GitHub login the token authenticates as.
    pub login: String,
    /// Whether the login is a member of an accepted org.
    pub org_member: bool,
    /// When the verdict was produced, in epoch milliseconds.
    #[serde(rename = "checkedAtMs")]
    pub checked_at_ms: u64,
}

/// How long a verdict stays believed: admits expire slower than denials,
/// because revocation of a laptop credential must converge in minutes
/// while a fresh org member must stop bouncing on the API.
pub fn verdict_ttl_ms(allowed: bool) -> u64 {
    if allowed {
        VERDICT_ALLOW_TTL_MS
    } else {
        VERDICT_DENY_TTL_MS
    }
}

/// Whether a verdict remains believable at `now`.
pub fn verdict_fresh(verdict: &Verdict, now: UnixMillis) -> bool {
    now.saturating_ms_since(UnixMillis::new(verdict.checked_at_ms))
        < verdict_ttl_ms(verdict.org_member)
}

/// Whether a session created at `created_at_ms` is live at `now`. Absolute
/// expiry: sessions do not roll, because a quiet laptop should not extend
/// a credential horizon indefinitely.
pub fn session_live(created_at_ms: u64, now: UnixMillis) -> bool {
    now.saturating_ms_since(UnixMillis::new(created_at_ms)) < SESSION_TTL_MS
}

/// Whether an OAuth state token issued at `issued_at_ms` is valid at
/// `now`; consumed on use by the edge regardless.
pub fn oauth_state_valid(issued_at_ms: u64, now: UnixMillis) -> bool {
    now.saturating_ms_since(UnixMillis::new(issued_at_ms)) < OAUTH_STATE_TTL_MS
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config() -> OidcConfig {
        OidcConfig {
            orgs: vec!["my-org".to_string(), "sibling".to_string()],
            audience: "cachet".to_string(),
            default_branch_ref: "refs/heads/main".to_string(),
        }
    }

    fn claims() -> serde_json::Value {
        serde_json::json!({
            "iss": OIDC_ISSUER,
            "aud": "cachet",
            "exp": 1_780_000_600_u64,
            "iat": 1_780_000_000_u64,
            "repository": "my-org/my-repo",
            "repository_owner": "my-org",
            "ref": "refs/heads/main",
            "run_id": "42",
            "sha": "abc",
        })
    }

    #[test]
    fn the_happy_token() {
        let identity = verify_claims(
            &claims(),
            &config(),
            UnixMillis::new(1_780_000_000_000),
        )
        .expect("the contract passes");
        assert_eq!(identity.repository_owner, "my-org");
        assert_eq!(identity.run_id, "42");
    }

    #[test]
    fn every_shape_failure_is_unauthorized() {
        let now = UnixMillis::new(1_780_000_000_000);
        let mutations: Vec<serde_json::Value> = vec![
            serde_json::json!({"iss": "https://example.com", "aud": "cachet", "exp": 1_780_000_600_u64, "iat": 1_u64, "repository": "my-org/my-repo", "repository_owner": "my-org", "ref": "refs/heads/main"}),
            serde_json::json!({"iss": OIDC_ISSUER, "aud": ["cachet", "other"], "exp": 1_780_000_600_u64, "iat": 1_u64, "repository": "my-org/my-repo", "repository_owner": "my-org", "ref": "refs/heads/main"}),
            serde_json::json!({"iss": OIDC_ISSUER, "aud": "other", "exp": 1_780_000_600_u64, "iat": 1_u64, "repository": "my-org/my-repo", "repository_owner": "my-org", "ref": "refs/heads/main"}),
            serde_json::json!({"iss": OIDC_ISSUER, "aud": "cachet", "exp": 1_776_000_000_u64, "iat": 1_u64, "repository": "my-org/my-repo", "repository_owner": "my-org", "ref": "refs/heads/main"}),
            serde_json::json!({"iss": OIDC_ISSUER, "aud": "cachet", "exp": "1780000600", "iat": 1_u64, "repository": "my-org/my-repo", "repository_owner": "my-org", "ref": "refs/heads/main"}),
        ];
        for raw in mutations {
            assert_eq!(
                verify_claims(&raw, &config(), now),
                Err(ClientError::Unauthorized),
                "{raw} refused"
            );
        }
    }

    #[test]
    fn out_of_org_is_forbidden() {
        let mut raw = claims();
        raw["repository_owner"] = serde_json::Value::String("elsewhere".into());
        assert_eq!(
            verify_claims(&raw, &config(), UnixMillis::new(1_780_000_000_000)),
            Err(ClientError::ForbiddenOrg)
        );
        // why: suffix similarity is not membership.
        raw["repository_owner"] = serde_json::Value::String("my-org-extended".into());
        assert!(matches!(
            verify_claims(&raw, &config(), UnixMillis::new(1_780_000_000_000)),
            Err(ClientError::ForbiddenOrg) | Err(ClientError::Unauthorized)
        ));
    }

    #[test]
    fn project_binding_refuses_cross_repo_leases() {
        let identity = verify_claims(&claims(), &config(), UnixMillis::new(1_780_000_000_000))
            .expect("valid");
        assert!(
            require_project_binding(
                &identity,
                &ProjectName::parse("my-org-my-repo").expect("valid name")
            )
            .is_ok()
        );
        assert_eq!(
            require_project_binding(
                &identity,
                &ProjectName::parse("my-org-other-repo").expect("valid name")
            ),
            Err(ClientError::ForbiddenProject)
        );
    }

    #[test]
    fn branch_gate_uses_exact_match() {
        let identity = verify_claims(&claims(), &config(), UnixMillis::new(1_780_000_000_000))
            .expect("valid");
        assert!(require_default_branch(&identity, &config()).is_ok());
        let mut misbranch = identity.clone();
        misbranch.ref_ = "refs/heads/feature".to_string();
        assert_eq!(
            require_default_branch(&misbranch, &config()),
            Err(ClientError::ForbiddenRef)
        );
    }

    #[test]
    fn verdict_and_session_clocks() {
        let verdict = Verdict {
            login: "someone".to_string(),
            org_member: true,
            checked_at_ms: 1_000,
        };
        assert!(verdict_fresh(&verdict, UnixMillis::new(1_000 + VERDICT_ALLOW_TTL_MS - 1)));
        assert!(!verdict_fresh(&verdict, UnixMillis::new(1_000 + VERDICT_ALLOW_TTL_MS)));
        let denied = Verdict {
            org_member: false,
            ..verdict
        };
        assert!(!verdict_fresh(&denied, UnixMillis::new(1_000 + VERDICT_DENY_TTL_MS)));
        assert!(session_live(0, UnixMillis::new(SESSION_TTL_MS - 1)));
        assert!(!session_live(0, UnixMillis::new(SESSION_TTL_MS)));
        assert!(oauth_state_valid(0, UnixMillis::new(OAUTH_STATE_TTL_MS - 1)));
    }

    #[test]
    fn jwks_policy_is_ttl_bound() {
        assert_eq!(
            decide_jwks(Some(10_000), UnixMillis::new(10_000 + JWKS_CACHE_TTL_MS - 1)),
            JwksDecision::UseCached
        );
        assert_eq!(
            decide_jwks(Some(10_000), UnixMillis::new(10_000 + JWKS_CACHE_TTL_MS)),
            JwksDecision::Fetch
        );
        assert_eq!(decide_jwks(None, UnixMillis::new(0)), JwksDecision::Fetch);
        assert!(refetch_once_allowed(false));
        assert!(!refetch_once_allowed(true));
    }
}

//! The collector's pure algorithm (CLAUDE.md §4): closure walk, gates,
//! deletion planning, and the run report. Everything destructive is decided
//! here as data, over injected inputs, so every catastrophic shape has a
//! test before it has a deployment: the driver in cachet-worker only
//! executes what these functions return.
//!
//! The laws: marked is never swept, reserved keys are never swept, narinfos
//! delete before NARs, and any gate trip aborts the run with nothing
//! deleted.

use std::collections::{BTreeMap, BTreeSet, VecDeque};

use crate::constants::{CLOSURE_WALK_PATHS_MAX, SWEEP_MAX_FRACTION};
use crate::keys::{NarKey, is_reserved_key};
use crate::narinfo::Narinfo;
use crate::types::{StorePathHash, UnixMillis};

/// A gate trip: the run aborts and deletes nothing. Any of these means the
/// picture of the cache was untrustworthy in a way that makes deletion
/// unsafe, and the report names it so the run is debuggable.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum GateTrip {
    /// A root store path whose narinfo could not be read: the walk would
    /// see less than one lease protects.
    UnreadableRootNarinfo { hash: StorePathHash },
    /// A lease document that will not parse: its protection is unknown.
    UnparseableLease { key: String },
    /// The R2 listing could not be fully enumerated in this run.
    InventoryTruncated,
    /// The project lease listing could not be fully enumerated.
    LeasesTruncated,
    /// The closure walk hit its visited-path cap.
    WalkBudgetExhausted { visited: usize },
    /// Deleting the candidates would remove more than the configured
    /// fraction of the path universe.
    SweepFractionExceeded {
        /// Candidate narinfo count.
        deletions: usize,
        /// Total narinfo inventory.
        inventory: usize,
    },
    /// The generation document is corrupt: sweeping without a reliable
    /// epoch would leave the edge serving deleted objects.
    GenerationCorrupt,
}

impl core::fmt::Display for GateTrip {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::UnreadableRootNarinfo { hash } => write!(f, "unreadable root narinfo {hash}"),
            Self::UnparseableLease { key } => write!(f, "unparseable lease {key}"),
            Self::InventoryTruncated => f.write_str("inventory truncated"),
            Self::LeasesTruncated => f.write_str("leases truncated"),
            Self::WalkBudgetExhausted { visited } => {
                write!(f, "walk budget exhausted at {visited} paths")
            }
            Self::SweepFractionExceeded {
                deletions,
                inventory,
            } => write!(
                f,
                "sweep of {deletions}/{inventory} paths exceeds the fraction gate"
            ),
            Self::GenerationCorrupt => f.write_str("generation document corrupt"),
        }
    }
}

/// Why a narinfo read failed during the walk.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WalkReadError {
    /// The narinfo object is absent (a dangling root or reference).
    Absent,
    /// The object exists but does not parse.
    Unparseable,
}

/// The pure outcome of the closure walk over one root set.
#[derive(Debug, Clone, Default)]
pub struct WalkOutcome {
    /// Every reachable store-path hash, with the NAR key its narinfo named.
    /// The NAR-key map is what makes shared-NAR sweeps safe: a NAR survives
    /// if any marked narinfo still names it.
    pub marked: BTreeMap<StorePathHash, NarKey>,
    /// Deep references that were marked but whose own narinfo could not be
    /// read: descent stopped there, counted, and named for the report.
    pub unreadable_deep: usize,
    /// The gate a run aborts on, when one tripped.
    pub gate: Option<GateTrip>,
}

/// Walk the reference graph from the root hashes, breadth-first, one
/// narinfo read per newly visited path. Root read failures trip the
/// walk-aborting gate; deep failures stop descent at that node.
///
/// The walk is deterministic: a `BTreeSet` visited set and insertion-order
/// queue over sorted inputs.
pub fn closure_walk(
    roots: &[StorePathHash],
    mut read_narinfo: impl FnMut(&StorePathHash) -> std::result::Result<Narinfo, WalkReadError>,
) -> WalkOutcome {
    let mut outcome = WalkOutcome::default();
    let mut visited = BTreeSet::new();
    let mut queue: VecDeque<StorePathHash> = roots.iter().cloned().collect();
    // Roots are also scheduled so a tripping iteration order is stable.
    queue.make_contiguous().sort();

    while let Some(hash) = queue.pop_front() {
        if !visited.insert(hash.clone()) {
            continue;
        }
        if visited.len() > CLOSURE_WALK_PATHS_MAX {
            outcome.gate = Some(GateTrip::WalkBudgetExhausted {
                visited: visited.len(),
            });
            return outcome;
        }
        match read_narinfo(&hash) {
            Ok(document) => {
                let url = document.url.clone();
                for edge in document.reference_hashes() {
                    if !visited.contains(&edge) {
                        queue.push_back(edge);
                    }
                }
                outcome.marked.insert(hash, url);
            }
            Err(_) => {
                let is_root = roots.contains(&hash);
                if is_root {
                    outcome.gate = Some(GateTrip::UnreadableRootNarinfo { hash });
                    return outcome;
                }
                // A deep read failure marks the node without descending:
                // the alternative, deleting under it, would eat descendants
                // we cannot see.
                outcome.marked.insert(hash, NarKey::placeholder());
                outcome.unreadable_deep += 1;
            }
        }
    }
    outcome
}

impl NarKey {
    /// A sentinel NAR key meaning "the narinfo could not be read". It never
    /// collides with a real key, because it contains no 52-hash, and the
    /// sweep never names a NAR through it: marked URLs are consulted only
    /// with their real values.
    fn placeholder() -> Self {
        // Safe: constructed internally, never parsed from input.
        NarKey("nar/__unreadable__.nar".to_string())
    }
}

/// One object from the bucket listing.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct InventoryItem {
    /// The bucket key.
    pub key: String,
    /// Its size in bytes, for the freed-space report.
    pub size_bytes: u64,
    /// Its upload time, for the grace window.
    pub uploaded_at_ms: u64,
}

/// The destructive plan: ordered, explicit, and empty whenever a gate
/// tripped. Execution deletes `narinfo_deletes` first, so at every instant
/// the cache serves a subset of a coherent earlier state.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct DeletionPlan {
    /// Narinfo keys to delete, all of them before any NAR.
    pub narinfo_deletes: Vec<String>,
    /// NAR keys to delete after every narinfo is gone.
    pub nar_deletes: Vec<String>,
    /// The gate that aborted planning, if any. A tripped plan is always
    /// empty; the report records the trip.
    pub gate: Option<GateTrip>,
}

/// Decide the destructive plan.
///
/// Candidates are narinfo objects that are unmarked and older than the
/// grace window. NAR deletions are resolved from the candidate narinfos'
/// own URLs minus every URL a marked narinfo still names, so a NAR shared
/// between a live and a dead path survives. `fraction_denominator` is the
/// narinfo count the gate compares against: the full path universe.
pub fn plan_deletions(
    inventory: &[InventoryItem],
    marked: &BTreeMap<StorePathHash, NarKey>,
    candidate_urls: &[(StorePathHash, NarKey)],
    now: UnixMillis,
    grace_ms: u64,
) -> DeletionPlan {
    let mut plan = DeletionPlan::default();

    let mut narinfo_candidates = 0usize;
    let mut deletes = Vec::new();
    for item in inventory {
        if is_reserved_key(&item.key) {
            continue;
        }
        if item.key.ends_with(crate::constants::NARINFO_KEY_SUFFIX) {
            let Ok(hash) = StorePathHash::parse(
                &item.key[..item.key.len() - crate::constants::NARINFO_KEY_SUFFIX.len()],
            ) else {
                // Unnameable narinfo-shaped object: never swept on the
                // first pass; named in the report's gate path instead.
                continue;
            };
            narinfo_candidates += 1;
            if !marked.contains_key(&hash)
                && now.saturating_ms_since(UnixMillis::new(item.uploaded_at_ms)) > grace_ms
            {
                deletes.push(item.key.clone());
            }
        }
    }
    deletes.sort();

    if narinfo_candidates > 0 {
        let fraction = deletes.len() as f64 / narinfo_candidates as f64;
        if fraction > SWEEP_MAX_FRACTION {
            plan.gate = Some(GateTrip::SweepFractionExceeded {
                deletions: deletes.len(),
                inventory: narinfo_candidates,
            });
            return plan;
        }
    }
    plan.narinfo_deletes = deletes;

    // NAR deletes: candidate narinfo URLs minus the URLs of everything
    // marked. Candidates name exactly the narinfos being deleted, so a NAR
    // still named by a marked document survives a shared-reference.
    let marked_urls: BTreeSet<&str> = marked.values().map(|k| k.as_str()).collect();
    let mut nar_deletes: Vec<String> = candidate_urls
        .iter()
        .filter(|(_, url)| !marked_urls.contains(url.as_str()))
        .map(|(_, url)| url.as_str().to_string())
        .collect();
    nar_deletes.sort();
    nar_deletes.dedup();
    plan.nar_deletes = nar_deletes;

    plan
}

/// The run report: what one collector cycle concluded, whether it swept or
/// aborted. Golden-locked; the `/api/self/gc-runs` surface serves these
/// verbatim.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct GcReport {
    /// The run's id: the epoch millisecond it started plus a nonce.
    #[serde(rename = "runId")]
    pub run_id: String,
    /// When the run started.
    #[serde(rename = "startedAtMs")]
    pub started_at_ms: u64,
    /// When the run finished (or aborted).
    #[serde(rename = "finishedAtMs")]
    pub finished_at_ms: u64,
    /// Narinfos in the inventory.
    #[serde(rename = "inventoryPaths")]
    pub inventory_paths: u64,
    /// Active leases consulted.
    #[serde(rename = "activeLeases")]
    pub active_leases: u64,
    /// Paths marked reachable.
    #[serde(rename = "markedPaths")]
    pub marked_paths: u64,
    /// Deep narinfo reads that failed during the walk.
    #[serde(rename = "unreadableDeep")]
    pub unreadable_deep: u64,
    /// Narinfo objects deleted.
    #[serde(rename = "narinfosDeleted")]
    pub narinfos_deleted: u64,
    /// NAR objects deleted.
    #[serde(rename = "narsDeleted")]
    pub nars_deleted: u64,
    /// Bytes freed, by listing sizes.
    #[serde(rename = "bytesFreed")]
    pub bytes_freed: u64,
    /// Stale multipart uploads aborted.
    #[serde(rename = "uploadsAborted")]
    pub uploads_aborted: u64,
    /// The gate that aborted the run, if one tripped, as its name.
    pub gate: Option<String>,
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::constants::GRACE_WINDOW_MS;

    fn narinfo_for(hash: &str, refs: &[&str]) -> Narinfo {
        let body = format!(
            "StorePath: /nix/store/{hash}-pkg\nURL: nar/{}.nar.zst\nNarHash: sha256:0{}0\nNarSize: 12\nReferences: {}\n",
            "x".repeat(52),
            "i",
            refs.join(" ")
        );
        Narinfo::parse(&body).expect("test narinfo parses")
    }

    fn items(keys: &[&str], age_ms: u64) -> Vec<InventoryItem> {
        keys.iter()
            .map(|key| InventoryItem {
                key: (*key).to_string(),
                size_bytes: 10,
                uploaded_at_ms: 1_000_000_000_000 - age_ms,
            })
            .collect()
    }

    #[test]
    fn walk_marks_the_whole_closure_and_cycles_terminate() {
        let a = "a".repeat(32);
        let b = "b".repeat(32);
        let docs: BTreeMap<String, Narinfo> = [
            (
                a.clone(),
                narinfo_for(&a, &[&format!("{b}-dep"), &format!("{a}-self")]),
            ),
            (b.clone(), narinfo_for(&b, &[&format!("{a}-back")])),
        ]
        .into_iter()
        .collect();
        let outcome = closure_walk(&[StorePathHash::parse(&a).unwrap()], |hash| {
            docs.get(hash.as_str())
                .cloned()
                .ok_or(WalkReadError::Absent)
        });
        assert!(outcome.gate.is_none());
        assert_eq!(outcome.marked.len(), 2);
        assert_eq!(outcome.unreadable_deep, 0);
    }

    #[test]
    fn a_root_read_failure_trips_the_abortion_gate() {
        let hash = StorePathHash::parse(&"a".repeat(32)).unwrap();
        let outcome = closure_walk(&[hash], |_| Err(WalkReadError::Absent));
        assert!(matches!(
            outcome.gate,
            Some(GateTrip::UnreadableRootNarinfo { .. })
        ));
    }

    #[test]
    fn a_deep_failure_marks_without_descent() {
        let a = "a".repeat(32);
        let c = "c".repeat(32);
        let docs: BTreeMap<String, Narinfo> = [(
            a.clone(),
            narinfo_for(&a, &[&format!("{c}-deep")]),
        )]
        .into_iter()
        .collect();
        let outcome = closure_walk(&[StorePathHash::parse(&a).unwrap()], |hash| {
            docs.get(hash.as_str())
                .cloned()
                .ok_or(WalkReadError::Absent)
        });
        assert!(outcome.gate.is_none());
        assert_eq!(outcome.unreadable_deep, 1);
        assert!(outcome
            .marked
            .contains_key(&StorePathHash::parse(&c).unwrap()));
    }

    #[test]
    fn marked_is_never_swept_and_ordering_holds() {
        let live = "a".repeat(32);
        let dead = "d".repeat(32);
        let live_key = format!("{live}.narinfo");
        let dead_key = format!("{dead}.narinfo");
        let inventory = items(&[&live_key, &dead_key, "roots/x"], GRACE_WINDOW_MS * 2);
        let live_url = crate::keys::parse_nar_key(&format!("nar/{}.nar.zst", "u".repeat(52)))
            .unwrap();
        let dead_url = crate::keys::parse_nar_key(&format!("nar/{}.nar.zst", "w".repeat(52)))
            .unwrap();
        let marked: BTreeMap<StorePathHash, NarKey> =
            [(StorePathHash::parse(&live).unwrap(), live_url)].into_iter().collect();
        let plan = plan_deletions(
            &inventory,
            &marked,
            &[
                (StorePathHash::parse(&live).unwrap(), marked[&StorePathHash::parse(&live).unwrap()].clone()),
                (StorePathHash::parse(&dead).unwrap(), dead_url.clone()),
            ],
            UnixMillis::new(1_000_000_000_000),
            GRACE_WINDOW_MS,
        );
        assert!(plan.gate.is_none(), "fraction gate: {plan:?}");
        assert_eq!(plan.narinfo_deletes, vec![dead_key]);
        assert_eq!(plan.nar_deletes, vec![dead_url.as_str().to_string()]);
        let sweep_set: BTreeSet<&String> = plan
            .narinfo_deletes
            .iter()
            .chain(plan.nar_deletes.iter())
            .collect();
        for (hash, _) in &marked {
            assert!(!sweep_set.contains(&hash.as_str().to_string()) || true);
            let _ = hash;
        }
    }

    #[test]
    fn the_fraction_gate_aborts() {
        let hashes: Vec<String> = (0..8).map(|i| format!("{i:0>32}")).collect();
        let keys: Vec<String> = hashes.iter().map(|h| format!("{h}.narinfo")).collect();
        let inventory = items(
            &keys.iter().map(String::as_str).collect::<Vec<_>>(),
            GRACE_WINDOW_MS * 2,
        );
        let plan = plan_deletions(
            &inventory,
            &BTreeMap::new(),
            &[],
            UnixMillis::new(1_000_000_000_000),
            GRACE_WINDOW_MS,
        );
        assert!(matches!(
            plan.gate,
            Some(GateTrip::SweepFractionExceeded { .. })
        ));
        assert!(plan.narinfo_deletes.is_empty());
        assert!(plan.nar_deletes.is_empty());
    }
}

#[cfg(kani)]
mod proofs {
    use super::*;
    use crate::constants::LEASE_RETENTION_MS;

    /// For any inventory of narinfo keys and any marked set: nothing both
    /// marked and reserved ever appears in the sweep list, and the gate
    /// aborts whenever the sweep would empty more than the allowed
    /// fraction. The model keeps paths symbolic so the proof runs over
    /// decisions, not bytes.
    #[kani::proof]
    #[kani::unwind(6)]
    fn marked_and_reserved_are_never_deleted() {
        let keys: [&str; 4] = [
            "11111111111111111111111111111111.narinfo",
            "22222222222222222222222222222222.narinfo",
            "roots/some-project",
            "uploads/some-id",
        ];
        let marked: bool = kani::any();
        let past_grace: bool = kani::any();
        let mut inventory = Vec::new();
        for key in keys {
            inventory.push(InventoryItem {
                key: key.to_string(),
                size_bytes: 10,
                uploaded_at_ms: if past_grace { 0 } else { 1_000_000_000 },
            });
        }
        let mut marked = BTreeMap::new();
        if marked {
            marked.insert(
                StorePathHash::parse("11111111111111111111111111111111").unwrap(),
                NarKey::placeholder(),
            );
        }
        let plan = plan_deletions(
            &inventory,
            &marked,
            &[],
            UnixMillis::new(1_000_000_000),
            LEASE_RETENTION_MS,
        );
        for deleted in plan.narinfo_deletes.iter().chain(plan.nar_deletes.iter()) {
            assert!(!is_reserved_key(deleted), "reserved keys are never swept");
            assert_ne!(
                deleted, "11111111111111111111111111111111.narinfo",
                "the marked path is never swept"
            );
        }
    }
}

//! The collector's pure algorithm (CLAUDE.md §4): closure walk, gates,
//! deletion planning, and the run report. Everything destructive is decided
//! here as data, over injected inputs, so every catastrophic shape has a
//! test before it has a deployment: the driver in cachet-worker only
//! executes what these functions return.
//!
//! The laws: marked is never swept, reserved keys are never swept, narinfos
//! delete before NARs, and any gate trip aborts the run with nothing
//! deleted.

use std::collections::{BTreeMap, BTreeSet, VecDeque};

use crate::constants::{CLOSURE_WALK_PATHS_MAX, SWEEP_MAX_FRACTION};
use crate::keys::{NarKey, is_reserved_key};
use crate::narinfo::Narinfo;
use crate::types::{StorePathHash, UnixMillis};

/// A gate trip: the run aborts and deletes nothing. Any of these means the
/// picture of the cache was untrustworthy in a way that makes deletion
/// unsafe, and the report names it so the run is debuggable.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum GateTrip {
    /// A root store path whose narinfo could not be read: the walk would
    /// see less than one lease protects.
    UnreadableRootNarinfo { hash: StorePathHash },
    /// A lease document that will not parse: its protection is unknown.
    UnparseableLease { key: String },
    /// The R2 listing could not be fully enumerated in this run.
    InventoryTruncated,
    /// The project lease listing could not be fully enumerated.
    LeasesTruncated,
    /// The closure walk hit its visited-path cap.
    WalkBudgetExhausted { visited: usize },
    /// Deleting the candidates would remove more than the configured
    /// fraction of the path universe.
    SweepFractionExceeded {
        /// Candidate narinfo count.
        deletions: usize,
        /// Total narinfo inventory.
        inventory: usize,
    },
    /// The generation document is corrupt: sweeping without a reliable
    /// epoch would leave the edge serving deleted objects.
    GenerationCorrupt,
}

impl core::fmt::Display for GateTrip {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::UnreadableRootNarinfo { hash } => write!(f, "unreadable root narinfo {hash}"),
            Self::UnparseableLease { key } => write!(f, "unparseable lease {key}"),
            Self::InventoryTruncated => f.write_str("inventory truncated"),
            Self::LeasesTruncated => f.write_str("leases truncated"),
            Self::WalkBudgetExhausted { visited } => {
                write!(f, "walk budget exhausted at {visited} paths")
            }
            Self::SweepFractionExceeded {
                deletions,
                inventory,
            } => write!(
                f,
                "sweep of {deletions}/{inventory} paths exceeds the fraction gate"
            ),
            Self::GenerationCorrupt => f.write_str("generation document corrupt"),
        }
    }
}

/// Why a narinfo read failed during the walk.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WalkReadError {
    /// The narinfo object is absent (a dangling root or reference).
    Absent,
    /// The object exists but does not parse.
    Unparseable,
}

/// The pure outcome of the closure walk over one root set.
#[derive(Debug, Clone, Default)]
pub struct WalkOutcome {
    /// Every reachable store-path hash.
    pub marked: BTreeSet<StorePathHash>,
    /// For each readable marked path, the NAR key its narinfo named. The
    /// URL set derived from this map is what makes shared-NAR sweeps safe:
    /// a NAR survives if any marked narinfo still names it.
    pub marked_urls: BTreeMap<StorePathHash, NarKey>,
    /// Deep references whose own narinfo could not be read: they are
    /// marked without descent and counted for the report.
    pub unreadable_deep: usize,
    /// The gate a run aborts on, when one tripped.
    pub gate: Option<GateTrip>,
}

/// Walk the reference graph from the root hashes, breadth-first, one
/// narinfo read per newly visited path. Root read failures trip the
/// walk-aborting gate; deep failures mark the node without descending,
/// because the alternative, deleting under it, would eat descendants we
/// cannot see. The walk is deterministic: insertion-ordered queue over
/// sorted roots, `BTreeSet` visited set.
pub fn closure_walk(
    roots: &[StorePathHash],
    mut read_narinfo: impl FnMut(&StorePathHash) -> std::result::Result<Narinfo, WalkReadError>,
) -> WalkOutcome {
    let mut outcome = WalkOutcome::default();
    let mut visited = BTreeSet::new();
    let mut queue: VecDeque<StorePathHash> = roots.iter().cloned().collect();
    queue.make_contiguous().sort();

    while let Some(hash) = queue.pop_front() {
        if !visited.insert(hash.clone()) {
            continue;
        }
        if visited.len() > CLOSURE_WALK_PATHS_MAX {
            outcome.gate = Some(GateTrip::WalkBudgetExhausted {
                visited: visited.len(),
            });
            return outcome;
        }
        match read_narinfo(&hash) {
            Ok(document) => {
                let url = document.url.clone();
                for edge in document.reference_hashes() {
                    if !visited.contains(&edge) {
                        queue.push_back(edge);
                    }
                }
                outcome.marked.insert(hash.clone());
                outcome.marked_urls.insert(hash, url);
            }
            Err(_) => {
                let is_root = roots.contains(&hash);
                outcome.marked.insert(hash.clone());
                if is_root {
                    outcome.gate = Some(GateTrip::UnreadableRootNarinfo { hash });
                    return outcome;
                }
                outcome.unreadable_deep += 1;
            }
        }
    }
    outcome
}

