//! Incremental zstd decoding over ruzstd (CLAUDE.md §5): the upload
//! verification pipeline streams a stored NAR through this decoder while a
//! hasher counts, so a bomb is bounded by output accounting, not by
//! buffer size. Errors are typed and total: truncated frames, corrupt
//! frames, and over-limit output all answer in [`ZstdError`].

use std::io::Read;

/// Why a decode failed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ZstdError {
    /// The frame bytes are corrupt or truncated.
    CorruptFrame,
    /// The frame produced more bytes than the caller's limit allows: a
    /// bomb guard, enforced stream-side rather than by buffering.
    LimitExceeded,
    /// The stream ended mid-frame: the declared NarSize was not
    /// reproducible from these bytes.
    Truncated,
}

impl core::fmt::Display for ZstdError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str(match self {
            Self::CorruptFrame => "corrupt zstd frame",
            Self::LimitExceeded => "decompressed size over the declared limit",
            Self::Truncated => "zstd stream ended mid-frame",
        })
    }
}

impl std::error::Error for ZstdError {}

/// One decoding pass over an in-memory frame. Exists for tests, the workerd
/// lane's harness, and the CLI; the worker's streaming path drives
/// [`ZstdStream`] instead.
///
/// # Errors
///
/// [`ZstdError`] on corrupt frames and on output over `limit` bytes.
pub fn decode_all(bytes: &[u8], limit: u64) -> Result<Vec<u8>, ZstdError> {
    let mut stream = ZstdStream::new(limit);
    stream.push(bytes)?;
    stream.finish()
}

/// The incremental decoder. Feeding is chunked by the caller; decoded
/// bytes come out per push; `finish` drains and validates completeness.
pub struct ZstdStream {
    decoder: Option<ruzstd::Decoder<Vec<u8>>>,
    output: Vec<u8>,
    limit: u64,
    decompressed: u64,
}

impl ZstdStream {
    /// Start a decode with an output cap. The cap should be the
    /// narinfo-declared NarSize: an honest NAR just fits, and a bomb
    /// cannot write past it.
    pub fn new(limit: u64) -> Self {
        Self {
            decoder: Some(ruzstd::Decoder::new(Vec::new())),
            output: Vec::new(),
            limit,
            decompressed: 0,
        }
    }

    /// Feed compressed bytes, receiving any decoded output they produce.
    ///
    /// # Errors
    ///
    /// [`ZstdError`] on corrupt frames or on output passing the limit.
    pub fn push(&mut self, bytes: &[u8]) -> Result<Vec<u8>, ZstdError> {
        let Some(decoder) = self.decoder.take() else {
            return Err(ZstdError::CorruptFrame);
        };
        let mut data = std::io::Cursor::new(bytes);
        let mut decoder = decoder;
        let mut buffer = vec![0u8; 64 * 1024];
        let mut produced = Vec::new();
        loop {
            match decoder.read(&mut buffer) {
                Ok(0) => {
                    if data.position() < data.get_ref().len() as u64 {
                        // Bytes remain but decode stalled: the frame is
                        // incomplete, and more input may still proceed.
                        break;
                    }
                    break;
                }
                Ok(n) => {
                    self.decompressed = self
                        .decompressed
                        .checked_add(u64::try_from(n).expect("len fits"))
                        .ok_or(ZstdError::LimitExceeded)?;
                    if self.decompressed > self.limit {
                        return Err(ZstdError::LimitExceeded);
                    }
                    produced.extend_from_slice(&buffer[..n]);
                }
                Err(ref e) if e.kind() == std::io::ErrorKind::UnexpectedEof => {
                    break;
                }
                Err(_) => return Err(ZstdError::CorruptFrame),
            }
        }
        self.output.extend_from_slice(&produced);
        self.decoder = Some(decoder);
        Ok(produced)
    }

    /// Drain and validate completeness: the whole input must have decoded
    /// into a finished frame.
    ///
    /// # Errors
    ///
    /// [`ZstdError::Truncated`] when the frame did not finish.
    pub fn finish(mut self) -> Result<Vec<u8>, ZstdError> {
        let Some(mut decoder) = self.decoder.take() else {
            return Err(ZstdError::CorruptFrame);
        };
        let mut buffer = vec![0u8; 64 * 1024];
        match decoder.read(&mut buffer) {
            Ok(_) => {}
            Err(_) => return Err(ZstdError::Truncated),
        }
        Ok(std::mem::take(&mut self.output))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const NAR_ZST: &[u8] = include_bytes!("../tests/fixtures/nix-signed/11lx23nn3dpc8mqp0ncnm6wqcxs6pfw32bp8n9c1fkafyzjvn16y.nar.zst");

    #[test]
    fn decodes_the_fixture_frame() {
        let plain = decode_all(NAR_ZST, 1_000_000).expect("the fixture decodes");
        assert_eq!(
            hex::encode(crate::sha256::sha256(&plain)),
            "fa15060475f784debf7dc8331ceca9e76ae633559df1f0f9860654afec2d95c5"
        );
    }

    #[test]
    fn a_truncated_frame_is_typed_not_panic() {
        let truncated = &NAR_ZST[..NAR_ZST.len() / 2];
        let outcome = decode_all(truncated, 1_000_000);
        assert!(matches!(
            outcome,
            Err(ZstdError::CorruptFrame) | Err(ZstdError::Truncated)
        ));
    }

    #[test]
    fn corruption_fails_cleanly() {
        let mut corrupted = NAR_ZST.to_vec();
        for byte in &mut corrupted[4..40] {
            *byte ^= 0xff;
        }
        assert!(decode_all(&corrupted, 1_000_000).is_err());
    }

    #[test]
    fn the_limit_is_enforced() {
        let outcome = decode_all(NAR_ZST, 10);
        assert_eq!(outcome, Err(ZstdError::LimitExceeded));
    }
}

//! cachet-crypto is the only place hashing, signing, and decompression
//! happen (CLAUDE.md §5): SHA-256 over streams, nix base32 and base64 hash
//! encodings, ed25519 signing of the nix narinfo fingerprint, zstd
//! decoding via ruzstd, and RS256/JWKS verification for GitHub OIDC. Every
//! function is pure and every dependency builds for wasm32-unknown-unknown;
//! deny.toml bans ring, aws-lc, and the C zstd crate from the whole tree.

#![forbid(unsafe_code)]
#![warn(missing_docs)]

pub mod base32;
pub mod ed25519;
pub mod rs256;
pub mod sha256;
pub mod zstd_stream;

//! RS256 verification and JWKS parsing for GitHub OIDC (CLAUDE.md §5).
//! `jose` has no Rust equivalent that builds for wasm32 without ring, so
//! verification is pure-rust `rsa` over parsed JWKs, with the claim policy
//! living in cachet-core: this module only proves (or refutes) that bytes
//! signed with a private key belong to a presented key.

use base64ct::{Base64UrlUnpadded, Encoding};

/// Why a JWT or JWKS input failed structurally.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum JwtError {
    /// Not three base64url segments.
    Shape,
    /// A segment was not base64url.
    Encoding,
    /// The header or claims were not JSON.
    Json,
    /// The JWK is not an RSA signing key.
    NotRsaSigningKey,
    /// Key material would not construct.
    KeyMaterial,
    /// The signature bytes were not a valid RS256 signature.
    Signature,
}

impl core::fmt::Display for JwtError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str(match self {
            Self::Shape => "a JWT has three base64url parts",
            Self::Encoding => "a JWT part is not base64url",
            Self::Json => "a JWT segment is not JSON",
            Self::NotRsaSigningKey => "a JWK is not an RSA signing key",
            Self::KeyMaterial => "the JWK integers do not form a key",
            Self::Signature => "the signature is not well-formed",
        })
    }
}

impl std::error::Error for JwtError {}

/// The pieces of a decoded JWT: header and claims JSON plus the signed
/// input and signature. Verification decisions (algorithm pinning,
/// audience, claims) live in cachet-core; this cut keeps the crypto
/// module honest about what it proved.
#[derive(Debug, Clone)]
pub struct DecodedJwt {
    /// The JOSE header (algorithm, key id), parsed JSON.
    pub header: serde_json::Value,
    /// The claims, parsed JSON.
    pub claims: serde_json::Value,
    /// `base64url(header).base64url(claims)`: exactly what RS256 signs.
    pub signing_input: String,
    /// The raw signature bytes.
    pub signature: Vec<u8>,
    /// The `kid` header field when present.
    pub kid: Option<String>,
}

/// Split a JWT into its verifiable pieces without trusting any field.
///
/// # Errors
///
/// [`JwtError`] on shape, encoding, or JSON failures.
pub fn decode_jwt(token: &str) -> Result<DecodedJwt, JwtError> {
    let mut parts = token.split('.');
    let (Some(h), Some(c), Some(s), None) = (parts.next(), parts.next(), parts.next(), parts.next())
    else {
        return Err(JwtError::Shape);
    };
    let header_bytes = Base64UrlUnpadded::decode_vec(h).map_err(|_| JwtError::Encoding)?;
    let claims_bytes = Base64UrlUnpadded::decode_vec(c).map_err(|_| JwtError::Encoding)?;
    let signature = Base64UrlUnpadded::decode_vec(s).map_err(|_| JwtError::Encoding)?;
    let header: serde_json::Value =
        serde_json::from_slice(&header_bytes).map_err(|_| JwtError::Json)?;
    let claims: serde_json::Value =
        serde_json::from_slice(&claims_bytes).map_err(|_| JwtError::Json)?;
    let kid = header
        .get("kid")
        .and_then(serde_json::Value::as_str)
        .map(str::to_string);
    Ok(DecodedJwt {
        header,
        claims,
        signing_input: format!("{h}.{c}"),
        signature,
        kid,
    })
}

/// A single RSA JWK from a JWKS document.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct RsaJwk {
    /// The key id.
    pub kid: String,
    /// The key type; must be `"RSA"`.
    pub kty: String,
    /// The modulus, base64url big-endian.
    pub n: String,
    /// The public exponent, base64url big-endian.
    pub e: String,
}

/// Verify an RS256 signature over `signing_input` under this JWK.
///
/// # Errors
///
/// [`JwtError`] when the key or signature does not construct; a signature
/// that verifies-false is `Ok(false)`, so callers distinguish broken
/// crypto plumbing from a dishonest token.
pub fn verify_rs256(jwk: &RsaJwk, signing_input: &str, signature: &[u8]) -> Result<bool, JwtError> {
    if jwk.kty != "RSA" {
        return Err(JwtError::NotRsaSigningKey);
    }
    let n_bytes = Base64UrlUnpadded::decode_vec(&jwk.n).map_err(|_| JwtError::Encoding)?;
    let e_bytes = Base64UrlUnpadded::decode_vec(&jwk.e).map_err(|_| JwtError::Encoding)?;
    let key = rsa::RsaPublicKey::new(
        rsa::BigUint::from_bytes_be(&n_bytes),
        rsa::BigUint::from_bytes_be(&e_bytes),
    )
    .map_err(|_| JwtError::KeyMaterial)?;
    let signature = rsa::pss::Signature::try_from(signature).map_err(|_| JwtError::Signature)?;
    let scheme = rsa::Pkcs1v15Sign::new::<sha2::Sha256>();
    Ok(rsa::signature::Verifier::verify(&key, signing_input.as_bytes(), &signature).is_ok())
}

