pub fn verify_rs256(jwk: &RsaJwk, signing_input: &str, signature: &[u8]) -> Result<bool, JwtError> {
    if jwk.kty != "RSA" {
        return Err(JwtError::NotRsaSigningKey);
    }
    let n_bytes = Base64UrlUnpadded::decode_vec(&jwk.n).map_err(|_| JwtError::Encoding)?;
