/// The incremental decoder. `push` feeds compressed chunks and returns
/// what they decoded to; `finish` validates that the stream ended on a
/// frame boundary.
pub struct ZstdStream {
    pipe: Pipe,
    // why: StreamingDecoder::new reads the frame header eagerly, and a
    // header can span pushes, so construction defers until the pipe has
    // enough to satisfy it; on failure the cursor rewinds and the next
    // push retries over the same bytes plus new ones.
    decoder: Option<ruzstd::StreamingDecoder<Pipe, ruzstd::FrameDecoder>>,
    limit: u64,
    decompressed: u64,
    closed: bool,
}

impl ZstdStream {
    /// Start a decode with an output cap. The cap should be the
    /// narinfo-declared NarSize: an honest NAR just fits, and a bomb
    /// cannot write past it.
    pub fn new(limit: u64) -> Self {
        Self {
            pipe: Pipe::default(),
            decoder: None,
            limit,
            decompressed: 0,
            closed: false,
        }
    }

    /// Feed compressed bytes, returning the decoded output they produced.
    ///
    /// # Errors
    ///
    /// [`ZstdError`] on corrupt frames, over-limit output, or (after
    /// [`ZstdStream::finish`]) on a stream that ends mid-frame.
    pub fn push(&mut self, bytes: &[u8]) -> Result<Vec<u8>, ZstdError> {
        self.pipe.append(bytes);
        let mut produced = Vec::new();
        let mut staging = vec![0u8; 64 * 1024];
        loop {
            // Construct the decoder the first time the pipe can satisfy
            // its eager header read.
            if self.decoder.is_none() {
                let position = self.pipe.position();
                match ruzstd::StreamingDecoder::new(self.pipe.clone()) {
                    Ok(decoder) => self.decoder = Some(decoder),
                    Err(_) => {
                        self.pipe.set_position(position);
                        if self.closed {
                            return Err(ZstdError::Truncated);
                        }
                        if self.pipe.pending() > 0 && bytes.is_empty() {
                            // More input produced no forward progress on a
                            // closed stream: corrupt framing.
                            return Err(ZstdError::CorruptFrame);
                        }
                        if self.pipe.pending() >= 64 {
                            // 64 bytes always cover a real frame header;
                            // failing there is a malformed frame, not
                            // backpressure.
                            return Err(ZstdError::CorruptFrame);
                        }
                        return Ok(produced);
                    }
                }
            }
            let Some(decoder) = self.decoder.as_mut() else {
                continue;
            };
            match decoder.read(&mut staging) {
                Ok(0) => break,
                Ok(n) => {
                    self.decompressed = self
                        .decompressed
                        .checked_add(u64::try_from(n).expect("len fits"))
                        .ok_or(ZstdError::LimitExceeded)?;
                    if self.decompressed > self.limit {
                        return Err(ZstdError::LimitExceeded);
                    }
                    produced.extend_from_slice(&staging[..n]);
                }
                Err(error) => {
                    let backpressure = error.kind() == std::io::ErrorKind::UnexpectedEof;
                    if backpressure && !self.closed && self.pipe.pending() == 0 {
                        // The frame wants more input than it has: legal
                        // until the producer closes the stream.
                        break;
                    }
                    if backpressure {
                        return Err(ZstdError::Truncated);
                    }
                    return Err(ZstdError::CorruptFrame);
                }
            }
        }
        Ok(produced)
    }

    /// Signal the end of input and drain. The frame must complete inside
    /// the already-fed bytes.
    ///
    /// # Errors
    ///
    /// [`ZstdError::Truncated`] when the frame never completed.
    pub fn finish(&mut self) -> Result<(), ZstdError> {
        self.closed = true;
        self.push(&[]).map(|_| ())
    }

    /// Total decompressed bytes seen so far.
    pub const fn decompressed_bytes(&self) -> u64 {
        self.decompressed
    }
}

