1	//! The collector's pure algorithm (CLAUDE.md §4): closure walk, gates,
2	//! deletion planning, and the run report. Everything destructive is decided
3	//! here as data, over injected inputs, so every catastrophic shape has a
4	//! test before it has a deployment: the driver in cachet-worker only
5	//! executes what these functions return.
6	//!
7	//! The laws: marked is never swept, reserved keys are never swept, narinfos
8	//! delete before NARs, and any gate trip aborts the run with nothing
9	//! deleted.
10	
11	use std::collections::{BTreeMap, BTreeSet, VecDeque};
12	
13	use crate::constants::{
14	    CLOSURE_WALK_PATHS_MAX, SWEEP_MAX_FRACTION_DENOMINATOR, SWEEP_MAX_FRACTION_NUMERATOR,
15	};
16	use crate::keys::{NarKey, is_reserved_key};
17	use crate::narinfo::Narinfo;
18	use crate::types::{StorePathHash, UnixMillis};
19	
20	/// A gate trip: the run aborts and deletes nothing. Any of these means the
21	/// picture of the cache was untrustworthy in a way that makes deletion
22	/// unsafe, and the report names it so the run is debuggable.
23	#[derive(Debug, Clone, PartialEq, Eq)]
24	pub enum GateTrip {
25	    /// A root store path whose narinfo could not be read: the walk would
26	    /// see less than one lease protects.
27	    UnreadableRootNarinfo {
28	        /// The root hash that failed to read.
29	        hash: StorePathHash,
30	    },
31	    /// A lease document that will not parse: its protection is unknown.
32	    UnparseableLease {
33	        /// The lease's bucket key.
34	        key: String,
35	    },
36	    /// The R2 listing could not be fully enumerated in this run.
37	    InventoryTruncated,
38	    /// The project lease listing could not be fully enumerated.
39	    LeasesTruncated,
40	    /// The closure walk hit its visited-path cap.
41	    WalkBudgetExhausted {
42	        /// The number of paths visited when the cap tripped.
43	        visited: usize,
44	    },
45	    /// Deleting the candidates would remove more than the configured
46	    /// fraction of the path universe.
47	    SweepFractionExceeded {
48	        /// Candidate narinfo count.
49	        deletions: usize,
50	        /// Total narinfo inventory.
51	        inventory: usize,
52	    },
53	    /// The generation document is corrupt: sweeping without a reliable
54	    /// epoch would leave the edge serving deleted objects.
55	    GenerationCorrupt,
56	}
57	
58	impl core::fmt::Display for GateTrip {
59	    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
60	        match self {
61	            Self::UnreadableRootNarinfo { hash } => write!(f, "unreadable root narinfo {hash}"),
62	            Self::UnparseableLease { key } => write!(f, "unparseable lease {key}"),
63	            Self::InventoryTruncated => f.write_str("inventory truncated"),
64	            Self::LeasesTruncated => f.write_str("leases truncated"),
65	            Self::WalkBudgetExhausted { visited } => {
66	                write!(f, "walk budget exhausted at {visited} paths")
67	            }
68	            Self::SweepFractionExceeded {
69	                deletions,
70	                inventory,
71	            } => write!(
72	                f,
73	                "sweep of {deletions}/{inventory} paths exceeds the fraction gate"
74	            ),
75	            Self::GenerationCorrupt => f.write_str("generation document corrupt"),
76	        }
77	    }
78	}
79	
80	/// Why a narinfo read failed during the walk.
81	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
82	pub enum WalkReadError {
83	    /// The narinfo object is absent (a dangling root or reference).
84	    Absent,
85	    /// The object exists but does not parse.
86	    Unparseable,
87	}
88	
89	/// The pure outcome of the closure walk over one root set.
90	#[derive(Debug, Clone, Default)]
91	pub struct WalkOutcome {
92	    /// Every reachable store-path hash.
93	    pub marked: BTreeSet<StorePathHash>,
94	    /// For each readable marked path, the NAR key its narinfo named. The
95	    /// URL set derived from this map is what makes shared-NAR sweeps safe:
96	    /// a NAR survives if any marked narinfo still names it.
97	    pub marked_urls: BTreeMap<StorePathHash, NarKey>,
98	    /// Deep references whose own narinfo could not be read: they are
99	    /// marked without descent and counted for the report.
100	    pub unreadable_deep: usize,
101	    /// The gate a run aborts on, when one tripped.
102	    pub gate: Option<GateTrip>,
103	}
104	
105	/// Walk the reference graph from the root hashes, breadth-first, one
106	/// narinfo read per newly visited path. Root read failures trip the
107	/// walk-aborting gate; deep failures mark the node without descending,
108	/// because the alternative, deleting under it, would eat descendants we
109	/// cannot see. The walk is deterministic: insertion-ordered queue over
110	/// sorted roots, `BTreeSet` visited set.
111	pub fn closure_walk(
112	    roots: &[StorePathHash],
113	    mut read_narinfo: impl FnMut(&StorePathHash) -> std::result::Result<Narinfo, WalkReadError>,
114	) -> WalkOutcome {
115	    let mut outcome = WalkOutcome::default();
116	    let mut visited = BTreeSet::new();
117	    let mut queue: VecDeque<StorePathHash> = roots.iter().cloned().collect();
118	    queue.make_contiguous().sort();
119	
120	    while let Some(hash) = queue.pop_front() {
121	        if !visited.insert(hash.clone()) {
122	            continue;
123	        }
124	        if visited.len() > CLOSURE_WALK_PATHS_MAX {
125	            outcome.gate = Some(GateTrip::WalkBudgetExhausted {
126	                visited: visited.len(),
127	            });
128	            return outcome;
129	        }
130	        if let Ok(document) = read_narinfo(&hash) {
131	            let url = document.url.clone();
132	            for edge in document.reference_hashes() {
133	                if !visited.contains(&edge) {
134	                    queue.push_back(edge);
135	                }
136	            }
137	            outcome.marked.insert(hash.clone());
138	            outcome.marked_urls.insert(hash, url);
139	        } else {
140	            let is_root = roots.contains(&hash);
141	            outcome.marked.insert(hash.clone());
142	            if is_root {
143	                outcome.gate = Some(GateTrip::UnreadableRootNarinfo { hash });
144	                return outcome;
145	            }
146	            outcome.unreadable_deep += 1;
147	        }
148	    }
149	    outcome
150	}
151	
152	/// One object from the bucket listing.
153	#[derive(Debug, Clone, PartialEq, Eq)]
154	pub struct InventoryItem {
155	    /// The bucket key.
156	    pub key: String,
157	    /// Its size in bytes, for the freed-space report.
158	    pub size_bytes: u64,
159	    /// Its upload time, in epoch milliseconds, for the grace window.
160	    pub uploaded_at_ms: u64,
161	}
162	
163	/// The destructive plan: ordered, explicit, and empty whenever a gate
164	/// tripped. Execution deletes `narinfo_deletes` first, so at every instant
165	/// the cache serves a subset of a coherent earlier state.
166	#[derive(Debug, Clone, Default, PartialEq, Eq)]
167	pub struct DeletionPlan {
168	    /// Narinfo keys to delete, all of them before any NAR.
169	    pub narinfo_deletes: Vec<String>,
170	    /// NAR keys to delete after every narinfo is gone.
171	    pub nar_deletes: Vec<String>,
172	    /// The gate that aborted planning, if any. A tripped plan is always
173	    /// empty; the report records the trip.
174	    pub gate: Option<GateTrip>,
175	}
176	
177	/// Decide the destructive plan.
178	///
179	/// Candidates are narinfo objects that are unmarked and older than the
180	/// grace window. NAR deletions resolve from the candidate narinfos' own
181	/// URLs minus every URL a marked narinfo still names, so a NAR shared
182	/// between a live and a dead path survives. The fraction gate compares
183	/// candidate count against the full narinfo inventory: a run that would
184	/// empty the cache is refused outright.
185	pub fn plan_deletions(
186	    inventory: &[InventoryItem],
187	    marked: &BTreeSet<StorePathHash>,
188	    marked_urls: &BTreeMap<StorePathHash, NarKey>,
189	    candidate_urls: &[(StorePathHash, NarKey)],
190	    now: UnixMillis,
191	    grace_ms: u64,
192	) -> DeletionPlan {
193	    let mut plan = DeletionPlan::default();
194	
195	    let mut narinfo_inventory = 0usize;
196	    let mut narinfo_deletes = Vec::new();
197	    for item in inventory {
198	        if is_reserved_key(&item.key) {
199	            continue;
200	        }
201	        if item.key.ends_with(crate::constants::NARINFO_KEY_SUFFIX) {
202	            let Ok(hash) = StorePathHash::parse(
203	                &item.key[..item.key.len() - crate::constants::NARINFO_KEY_SUFFIX.len()],
204	            ) else {
205	                // Unnameable narinfo-shaped object: it cannot map to a
206	                // lease-protected path either way, so plan says nothing and
207	                // the report's gate list has it noted by the driver.
208	                continue;
209	            };
210	            narinfo_inventory += 1;
211	            if !marked.contains(&hash)
212	                && now.saturating_ms_since(UnixMillis::new(item.uploaded_at_ms)) > grace_ms
213	            {
214	                narinfo_deletes.push(item.key.clone());
215	            }
216	        }
217	    }
218	    narinfo_deletes.sort();
219	
220	    // why: the fraction gate compares in integers, not floats: usize→f64
221	    // casts lose precision at pathological cache sizes, and a safety gate
222	    // must never silently widen.
223	    if narinfo_deletes.len() * SWEEP_MAX_FRACTION_DENOMINATOR
224	        > narinfo_inventory * SWEEP_MAX_FRACTION_NUMERATOR
225	    {
226	        plan.gate = Some(GateTrip::SweepFractionExceeded {
227	            deletions: narinfo_deletes.len(),
228	            inventory: narinfo_inventory,
229	        });
230	        return plan;
231	    }
232	    plan.narinfo_deletes = narinfo_deletes;
233	
234	    let live_urls: BTreeSet<&str> = marked_urls.values().map(NarKey::as_str).collect();
