/**
 * Serving objects: the edge cache, the bucket, and a cacheable miss.
 *
 * This module performs the reads and the caching and makes no protocol decisions. Which headers a
 * response carries, whether an object may be cached, and what a miss looks like are all decided in
 * `src/core/routes/read.ts`.
 *
 * @module
 */

import { GENERATION_EDGE_TTL_SECONDS, GENERATION_OBJECT_KEY } from '../core/constants.js';
import {
    generationCacheKey,
    objectCacheKey,
    parseGenerationDocument,
    serializeGenerationDocument,
} from '../core/routes/generation.js';
import {
    isEdgeCacheable,
    notFoundResponseHeaders,
    objectResponseHeaders,
    type ObjectKind,
} from '../core/routes/read.js';
import { GENERATION_ZERO, unixMillis, type Generation } from '../core/types.js';
import type { CachetEnv } from './env.js';
import { logEvent } from './log.js';
import type { WaitUntil } from './request.js';

/** The generation entry's own headers. Its short TTL is the staleness bound after a sweep. */
function generationCacheHeaders(): Record<string, string> {
    return {
        'Content-Type': 'application/json',
        'Cache-Control': `public, max-age=${String(GENERATION_EDGE_TTL_SECONDS)}`,
    };
}

/**
 * Resolve the current edge-cache generation.
 *
 * Read through the edge cache, so the common case costs a near-free match rather than a bucket
 * operation, with a short TTL bounding how long a stale value can be believed (ADR 0012).
 *
 * Returns `undefined` when the generation cannot be established, and the caller then bypasses the
 * edge cache rather than assuming zero. Reusing zero would resurrect entries written before the first
 * sweep, the staleness the generation exists to prevent.
 */
async function resolveGeneration(
    env: CachetEnv,
    waitUntil: WaitUntil,
): Promise<Generation | undefined> {
    const cache = caches.default;
    const cacheKey = new Request(generationCacheKey());

    const cached = await cache.match(cacheKey);
    if (cached !== undefined) {
        const parsed = parseGenerationDocument(await cached.text());
        if (parsed.ok) {
            return parsed.value.generation;
        }
        logEvent('alert', 'generation.cached_document_corrupt');
        return undefined;
    }

    const object = await env.CACHE_BUCKET.get(GENERATION_OBJECT_KEY);
    // An absent object means no sweep has ever run, so the generation is zero. That zero is worth
    // caching, so a fresh bucket does not pay a bucket read on every request.
    const document =
        object === null
            ? serializeGenerationDocument({
                  generation: GENERATION_ZERO,
                  bumpedAtMs: unixMillis(0),
              })
            : await object.text();

    const parsed = parseGenerationDocument(document);
    if (!parsed.ok) {
        logEvent('alert', 'generation.document_corrupt', { reason: parsed.error.code });
        return undefined;
    }

    waitUntil(cache.put(cacheKey, new Response(document, { headers: generationCacheHeaders() })));
    return parsed.value.generation;
}

/**
 * Answer a HEAD from the bucket's metadata alone.
 *
 * A HEAD is not edge-cached. Nix uses GET for the narinfo queries that matter, so HEAD traffic here
 * is rare and not worth a second cache-key space to reason about.
 */
export async function headObject(
    env: CachetEnv,
    bucketKey: string,
    kind: ObjectKind,
): Promise<Response> {
    const head = await env.CACHE_BUCKET.head(bucketKey);
    if (head === null) {
        return new Response(null, { status: 404, headers: notFoundResponseHeaders() });
    }
    return new Response(null, { headers: objectResponseHeaders(kind, head.size) });
}

/**
 * Serve one object: edge cache, then bucket, then a cacheable miss.
 *
 * The body is never buffered — R2 hands back a stream and it is passed straight through. Worker
 * memory is 128 MB and NARs are larger (`docs/contracts.md`).
 */
export async function serveObject(
    env: CachetEnv,
    requestPath: string,
    bucketKey: string,
    kind: ObjectKind,
    waitUntil: WaitUntil,
): Promise<Response> {
    const generation = await resolveGeneration(env, waitUntil);
    const cache = caches.default;
    const cacheKey =
        generation === undefined ? undefined : new Request(objectCacheKey(generation, requestPath));

    if (cacheKey !== undefined) {
        const hit = await cache.match(cacheKey);
        if (hit !== undefined) {
            logEvent('info', 'read.edge_hit', { kind });
            return hit;
        }
    }

    const object = await env.CACHE_BUCKET.get(bucketKey);
    if (object === null) {
        // An absent object is answered with a 404 rather than a 5xx, because Nix reads a 404 as "this
        // cache does not have it" and moves to the next substituter, while a 5xx would make it retry
        // (Invariant FAIL-TOWARD-REBUILD).
        logEvent('info', 'read.miss', { kind });
        const missing = new Response('not found\n', {
            status: 404,
            headers: notFoundResponseHeaders(),
        });
        if (cacheKey !== undefined) {
            waitUntil(cache.put(cacheKey, missing.clone()));
        }
        return missing;
    }

    const response = new Response(object.body, {
        headers: objectResponseHeaders(kind, object.size),
    });
    if (!isEdgeCacheable(object.size)) {
        // The read succeeded and the object is only too large to cache, so this line is a diagnostic
        // rather than a bug.
        logEvent('info', 'read.too_large_to_cache', { kind, sizeBytes: object.size });
    } else if (cacheKey !== undefined) {
        waitUntil(cache.put(cacheKey, response.clone()));
    }
    logEvent('info', 'read.bucket_hit', { kind });
    return response;
}
/**
 * The read path's decisions.
 *
 * Serving a narinfo or a NAR is mostly I/O — a cache lookup, a bucket read, a streamed body — and
 * that lives at the edge. What lives here is everything the edge would otherwise get subtly wrong:
 * which headers a response carries, whether an object may be cached, and what a miss looks
 * like.
 *
 * Two of these are easy to get wrong:
 *
 * - Every cacheable response carries an explicit `Cache-Control` with a positive `max-age`.
 *   The Cache API silently refuses to store a response without one (`docs/testing/workerd-pool.md`),
 *   so an omission here would make caching look correct and do nothing.
 * - A 404 is a cacheable answer rather than an error, because Nix reads it as "this cache does
 *   not have it" and moves to the next substituter (Invariant FAIL-TOWARD-REBUILD).
 *
 * @module
 */

import {
    CACHE_INFO_CONTENT_TYPE,
    EDGE_CACHE_OBJECT_BYTES_MAX,
    EDGE_TTL_CACHE_INFO_SECONDS,
    EDGE_TTL_NAR_SECONDS,
    EDGE_TTL_NARINFO_SECONDS,
    EDGE_TTL_NEGATIVE_SECONDS,
    NAR_CONTENT_TYPE,
    NARINFO_CONTENT_TYPE,
} from '../constants.js';

/** Which kind of object a read is serving. Decides the content type and the TTL. */
export type ObjectKind = 'narinfo' | 'nar';

/**
 * Headers for a successful object read.
 *
 * `immutable` is honest here: both kinds are content-addressed under a generation-scoped cache key,
 * so the bytes behind a key never change.
 *
 * @param sizeBytes - the object's size, used verbatim as `Content-Length` so a client can show
 *   progress and detect truncation
 */
export function objectResponseHeaders(kind: ObjectKind, sizeBytes: number): Record<string, string> {
    const ttlSeconds = kind === 'narinfo' ? EDGE_TTL_NARINFO_SECONDS : EDGE_TTL_NAR_SECONDS;
    return {
        'Content-Type': kind === 'narinfo' ? NARINFO_CONTENT_TYPE : NAR_CONTENT_TYPE,
        'Content-Length': String(sizeBytes),
        'Cache-Control': `public, max-age=${String(ttlSeconds)}, immutable`,
    };
}

/**
 * Headers for an object we do not have.
 *
 * A 404 carries a short positive `max-age`, so the edge caches it. Nix asks about a path before
 * every substitution, so an uncached 404 costs an R2 round trip per query; caching it for a few
 * seconds removes that cost, and keeping the window short means a freshly pushed path becomes
 * visible almost immediately.
 */
export function notFoundResponseHeaders(): Record<string, string> {
    return {
        'Content-Type': 'text/plain; charset=utf-8',
