/**
 * The write path's decisions.
 *
 * Two guards matter more than the rest:
 *
 * - A narinfo may not be stored unless its NAR already exists. That is the write-time half of
 *   Invariant NEVER-DANGLE, and the point is that it verifies the uploader's NAR-before-narinfo
 *   ordering rather than trusting it. A cache holding a narinfo whose NAR is missing hands clients
 *   a promise it cannot keep: Nix reads the metadata, asks for the archive, and fails a build that
 *   would otherwise have succeeded by building from source.
 * - A write without `Content-Length` is refused, because the size guard is what keeps the request
 *   bounded and cannot run on an unknown length (Invariant BOUNDED-WORK).
 *
 * @module
 */

import { fail, ok, type Result } from '../result.js';
import type { StorePathHash } from '../types.js';
import { parseStorePath } from '../wire/keys.js';
import type { Narinfo } from '../wire/narinfo.js';

/**
 * Require a declared body size within a cap.
 *
 * @param header - the `Content-Length` header, absent as `null` or `undefined`
 * @param capBytes - the largest body this route accepts
 *
 * @example
 * ```ts
 * const length = requireContentLength(request.headers.get('content-length'), UPLOAD_SINGLE_MAX_BYTES);
 * if (!length.ok) return length;
 * ```
 */
export function requireContentLength(
    header: string | null | undefined,
    capBytes: number,
): Result<number> {
    if (header === null || header === undefined || header.length === 0) {
        // 411 rather than 400: the request is well-formed, it is missing the one thing the
        // size guard needs, and the client can fix it by declaring a length.
        return fail('length_required', 'a write must declare Content-Length');
    }
    if (!/^\d+$/.test(header)) {
        return fail('length_required', 'Content-Length is a non-negative integer');
    }

    const lengthBytes = Number(header);
    if (!Number.isSafeInteger(lengthBytes)) {
        return fail('body_too_large', 'Content-Length is too large to represent exactly');
    }
    if (lengthBytes > capBytes) {
        return fail(
            'body_too_large',
            `a body of ${header} bytes exceeds the ${String(capBytes)}-byte cap`,
        );
    }
    return ok(lengthBytes);
}

/**
 * Decide whether a narinfo may be stored.
 *
 * Pure: the caller establishes whether the NAR exists and passes the answer in, which is what makes
 * Invariant NEVER-DANGLE's write-time half testable without a bucket.
 *
 * Two things are checked, and the first is easy to overlook. A narinfo is stored under the hash in
 * its request path, while the document carries a `StorePath` of its own. Nothing forces those to
 * agree, so without this check a client could store, under one path's key, metadata describing a
 * different path — and a reader asking about the first would receive an answer about the second.
 *
 * @param narinfo - the parsed document
 * @param expectedHash - the hash the request path named
 * @param narExists - whether `narinfo.url` names an object that is already in the bucket
 */
export function decideNarinfoWrite(
    narinfo: Narinfo,
    expectedHash: StorePathHash,
    narExists: boolean,
): Result<void> {
    const storePath = parseStorePath(narinfo.storePath);
    if (!storePath.ok) {
        // Unreachable through `parseNarinfo`, which validates this field — kept because this
        // function's contract should not depend on which caller found the document.
        return fail('malformed_narinfo', 'StorePath is not a valid store path');
    }
    if (storePath.value.hash !== expectedHash) {
        return fail(
            'malformed_narinfo',
            'the narinfo describes a different store path than the one it is being stored under',
        );
    }

    if (!narExists) {
        // 409 rather than 400: the document is well-formed. What is wrong is the order — the
        // uploader raced, or sent the narinfo first — and a correct client fixes it by uploading
        // the NAR and retrying, which is what a conflict means.
        return fail(
            'narinfo_nar_missing',
            `the NAR ${String(narinfo.url)} must be uploaded before its narinfo`,
        );
    }
    return ok(undefined);
}

/**
 * Multipart uploads.
 *
 * These routes exist for one reason: Cloudflare rejects a request body over 100 MB at the edge,
 * before the Worker runs, and NARs get larger than that (`docs/contracts.md`). So an object above
 * `UPLOAD_SINGLE_MAX_BYTES` arrives as a sequence of parts instead.
 *
 * R2 requires every part except the last to be exactly the same size, and it checks this at
 * `complete` — after every byte has already crossed the network. The Worker therefore checks it at
 * upload time, so a violation costs one request instead of an entire transfer. R2's own check
 * remains as the paired half (CLAUDE.md §5).
 *
 * Doing that requires knowing what size to expect, and `resumeMultipartUpload` carries no state: a
 * resumed handle exposes the key and the upload id and nothing else, a fact the truth lane pins
 * (`docs/testing/workerd-pool.md`). A stateless isolate has nowhere to remember what it promised —
 * hence the small bookkeeping object this module defines.
 *
 * @module
 */

import { assert } from '../assert.js';
import {
    COMPLETE_BODY_BYTES_MAX,
    MULTIPART_PARTS_MAX,
    UPLOAD_PART_BYTES,
    UPLOAD_RECORD_BYTES_MAX,
