    }
    return ok(undefined);
}

/**
 * Validate the part list a client sends to complete an upload.
 *
 * Requires exactly the planned parts, once each, in ascending order — which is both what R2 expects
 * and the only list that can reassemble the object the client declared.
 */
export function parseCompletionBody(
    text: string,
    record: UploadRecord,
): Result<readonly CompletedPart[]> {
    if (text.length > COMPLETE_BODY_BYTES_MAX) {
        return fail('body_too_large', 'the completion body exceeds its cap');
    }

    let parsed: unknown;
    try {
        parsed = JSON.parse(text);
    } catch {
        return fail('complete_parts_mismatch', 'the completion body is not valid JSON');
    }
    if (!Array.isArray(parsed)) {
        return fail('complete_parts_mismatch', 'the completion body is an array of parts');
    }
    if (parsed.length !== record.expectedParts) {
        return fail(
            'complete_parts_mismatch',
            `expected ${String(record.expectedParts)} parts, received ${String(parsed.length)}`,
        );
    }

