    for (const [index, entry] of parsed.entries()) {
        const part = parseCompletedPart(entry);
        if (!part.ok) {
            return part;
        }
        // Ascending and gapless, which also rules out duplicates without a second pass.
        if (part.value.partNumber !== index + 1) {
            return fail(
                'complete_parts_mismatch',
                'parts are listed in ascending order with no gaps',
            );
        }
